function translateText(text:string){if(currentLanguage==='en')return text;let out=text;for(const [en,bn] of Object.entries(translations))out=out.split(en).join(bn);return out}
function applyLanguage(){
  document.documentElement.lang=currentLanguage==='bn'?'bn':'en';
  document.title=currentLanguage==='bn'?'ইজিলার্ন ইনস্টিটিউট':'Easylearn Institute';
  if(currentLanguage==='bn'){
    const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);
    const nodes:Text[]=[];let n:Node|null;while((n=walker.nextNode()))nodes.push(n as Text);
    nodes.forEach(t=>{if(t.parentElement&& !['SCRIPT','STYLE'].includes(t.parentElement.tagName))t.nodeValue=translateText(t.nodeValue||'')});
    document.querySelectorAll<HTMLElement>('input[placeholder],textarea[placeholder]').forEach(el=>{const v=el.getAttribute('placeholder')||'';el.setAttribute('placeholder',translateText(v))});
  }
  const b=document.getElementById('languageToggle');if(b)b.textContent=currentLanguage==='bn'?'English':'বাংলা';
}
function toggleLanguage(){currentLanguage=currentLanguage==='en'?'bn':'en';localStorage.setItem('easylearn-language',currentLanguage);location.reload();}

// Progress 26: global network/loading/error state
function ensureAppStatusUI(){
  if(!document.getElementById('networkStatus')){
    document.body.insertAdjacentHTML('beforeend',`<div id="networkStatus" class="network-status online" role="status" aria-live="polite"></div><div id="globalLoading" class="global-loading" aria-hidden="true"><div class="loading-spinner"></div><span>Loading...</span></div>`);
  }
  updateNetworkStatus();
}
function updateNetworkStatus(){
  const el=document.getElementById('networkStatus');if(!el)return;
  const online=navigator.onLine;
  el.className=`network-status ${online?'online':'offline'}`;
  el.textContent=online?'':'You are offline — showing the app shell. Internet is required to load or save live institute data.';
}
function setGlobalLoading(on:boolean,text='Loading...'){
  const el=document.getElementById('globalLoading');if(!el)return;
  el.classList.toggle('show',on);el.setAttribute('aria-hidden',String(!on));
  const t=el.querySelector('span');if(t)t.textContent=text;
}
function showRuntimeError(message:string){
  const text=String(message||'Something went wrong.');
  console.error(text);
  const existing=document.getElementById('runtimeError');
  if(existing)existing.remove();
  document.body.insertAdjacentHTML('beforeend',`<div id="runtimeError" class="runtime-error"><b>Something went wrong</b><span>${esc(text)}</span><button onclick="this.parentElement.remove()">Dismiss</button></div>`);
}
window.addEventListener('online',()=>{updateNetworkStatus();const e=document.getElementById('networkStatus');if(e){e.textContent='Back online — live data can be loaded again.';setTimeout(updateNetworkStatus,3000)}});
window.addEventListener('offline',updateNetworkStatus);
window.addEventListener('unhandledrejection',e=>{setGlobalLoading(false);showRuntimeError(String((e as any).reason?.message||(e as any).reason||'Unexpected error'))});
window.addEventListener('error',e=>showRuntimeError((e as ErrorEvent).message||'Unexpected application error'));
ensureAppStatusUI();
const languageObserver=new MutationObserver(()=>{window.requestAnimationFrame(()=>applyLanguage())});
languageObserver.observe(app,{childList:true,subtree:true});
applyLanguage();

const esc=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!))
const initials=(n:string)=>n.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'ST'
const today=()=>new Date().toISOString().slice(0,10)

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.querySelectorAll<HTMLElement>('[data-install]').forEach(x=>x.style.display='inline-flex')})
window.addEventListener('appinstalled',()=>{installPrompt=null})
async function installApp(){if(!installPrompt){alert('Use your browser menu → Install app / Add to Home screen.');return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}
if('serviceWorker' in navigator) window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))

async function context(){
  const {data}=await supabase.auth.getSession(); const user=data.session?.user
  if(!user)return null
  const pa=await supabase.rpc('is_platform_admin'); isPlatformAdmin=!pa.error&&pa.data===true
  if(!instituteId){
    const r=await supabase.rpc('get_my_institute_id')
    if(r.error){console.error(r.error);return null}
    if(!r.data){await instituteSetup();return null}
    instituteId=String(r.data)
  }
  const rr=await supabase.rpc('get_my_role'); if(!rr.error&&rr.data) currentRole=String(rr.data)
  return {user,instituteId,role:currentRole}
}

async function instituteSetup(){
  const {data}=await supabase.auth.getSession(); if(!data.session){login();return}
  app.innerHTML=`<div class="login-page"><div class="login-card" style="max-width:720px"><div class="login-logo">E</div><h1>Set up your institute</h1><p class="login-subtitle">Create your institute workspace. Your account will become its administrator and a 30-day trial will start automatically.</p><div id="setupMsg" class="auth-message"></div><div class="form-grid">${field('instName','Institute Name *','e.g. Easylearn Institute')}${field('instPhone','Phone','01XXXXXXXXX')}${field('instEmail','Institute Email','info@example.com','email')}${field('instType','Institute Type','Coaching / School / Training')}<div class="form-group full-width"><label>Address</label><textarea id="instAddress" rows="3" placeholder="Institute address"></textarea></div></div><button class="primary-btn full" id="createInstituteBtn">Create Institute & Start Trial</button><button class="text-btn muted" id="setupLogout">Logout</button></div></div>`
  const msg=document.getElementById('setupMsg')!; const show=(t:string,e=false)=>{msg.textContent=t;msg.className=`auth-message ${e?'error':'success'}`}
  document.getElementById('setupLogout')!.onclick=async()=>{await supabase.auth.signOut();instituteId=null;login()}
  document.getElementById('createInstituteBtn')!.onclick=async()=>{
    const name=(document.getElementById('instName') as HTMLInputElement).value.trim();
    const phone=(document.getElementById('instPhone') as HTMLInputElement).value.trim();
    const email=(document.getElementById('instEmail') as HTMLInputElement).value.trim().toLowerCase();
    const type=(document.getElementById('instType') as HTMLInputElement).value.trim();
    const address=(document.getElementById('instAddress') as HTMLTextAreaElement).value.trim();
    if(!name)return show('Institute name is required.',true);
    if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return show('Please enter a valid institute email.',true);
    const b=document.getElementById('createInstituteBtn') as HTMLButtonElement;b.disabled=true;b.textContent='Creating institute...';
    try{const r=await supabase.rpc('create_my_institute',{p_name:name,p_phone:phone||null,p_email:email||null,p_type:type||null,p_address:address||null});if(r.error)return show(r.error.message,true);instituteId=String(r.data);show('Institute created successfully. Opening dashboard...');setTimeout(()=>dashboard(),500)}catch(e){show(authErrorMessage(e),true)}finally{b.disabled=false;b.textContent='Create Institute & Start Trial'}
  }
}

function header(back=true){return `<header class="topbar"><div class="brand"><div class="logo">E</div><div><div class="brand-name">Easylearn</div><div class="brand-sub">INSTITUTE</div></div></div><div class="topbar-actions">${back?'<button class="outline-btn" data-page="dashboard">← Dashboard</button>':''}${isPlatformAdmin?'<button class="outline-btn" data-page="platform-admin">SaaS Admin</button>':''}<button class="install-btn" data-install style="display:none">Install App</button><button class="logout-btn" data-logout>Logout</button></div></header>`}
function field(id:string,label:string,placeholder='',type='text',value=''){return `<div class="form-group"><label>${label}</label><input id="${id}" type="${type}" placeholder="${placeholder}" value="${esc(value)}"/></div>`}
function select(id:string,label:string,opts:string[],value=''){return `<div class="form-group"><label>${label}</label><select id="${id}"><option value="">Select</option>${opts.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`}
function bind(){document.getElementById('languageToggle')?.addEventListener('click',toggleLanguage);document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go((b as HTMLElement).dataset.page!)));document.querySelectorAll('[data-logout]').forEach(b=>b.addEventListener('click',async()=>{await supabase.auth.signOut();instituteId=null;login()}));document.querySelectorAll('[data-install]').forEach(b=>b.addEventListener('click',installApp))}

function authErrorMessage(error:any){
  const raw=String(error?.message||error||'Unknown error')
  const lower=raw.toLowerCase()
  if(lower.includes('failed to fetch')||lower.includes('network')||lower.includes('fetch')) return 'Supabase-এর সাথে সংযোগ করা যাচ্ছে না। ইন্টারনেট, .env এবং Supabase Project URL পরীক্ষা করুন।'
  if(lower.includes('email not confirmed')) return 'আপনার email এখনো confirm করা হয়নি। Email inbox থেকে confirmation link খুলুন।'
  if(lower.includes('invalid login credentials')) return 'Email অথবা password সঠিক নয়।'
  if(lower.includes('user already registered')) return 'এই email দিয়ে আগে থেকেই account আছে। Login করুন।'
  return raw
}
function authGuard(){
  if(supabaseConfigured)return true
  app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">E</div><h1>Easylearn Institute</h1><div class="auth-message error">Supabase configuration পাওয়া যায়নি। Project root-এ .env ফাইলে VITE_SUPABASE_URL এবং VITE_SUPABASE_PUBLISHABLE_KEY দিন।</div><button class="primary-btn full" onclick="location.reload()">Retry</button></div></div>`
  return false
}
function login(){
  if(!authGuard())return
  app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">E</div><h1>Easylearn Institute</h1><p class="login-subtitle">Sign in to your institute account</p><div id="msg" class="auth-message"></div>${field('email','Email','you@example.com','email')}${field('password','Password','Your password','password')}<button class="primary-btn full" id="loginBtn">Login</button><button class="text-btn" id="registerBtn">Create a new account</button><button class="text-btn muted" id="forgotBtn">Forgot password?</button></div></div>`
  const msg=document.getElementById('msg')!;const show=(t:string,e=false)=>{msg.textContent=t;msg.className=`auth-message ${e?'error':'success'}`}
  document.getElementById('loginBtn')!.onclick=async()=>{
    const email=(document.getElementById('email') as HTMLInputElement).value.trim().toLowerCase(),password=(document.getElementById('password') as HTMLInputElement).value
    if(!email||!password)return show('Please enter email and password.',true)
    const b=document.getElementById('loginBtn') as HTMLButtonElement;b.disabled=true;b.textContent='Signing in...'
    try{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)show(authErrorMessage(error),true);else await dashboard()}catch(e){show(authErrorMessage(e),true)}finally{b.disabled=false;b.textContent='Login'}
  }
  document.getElementById('registerBtn')!.onclick=register
  document.getElementById('forgotBtn')!.onclick=forgotPassword
}
function register(){
  if(!authGuard())return
  app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">E</div><h1>Create Account</h1><p class="login-subtitle">Register your institute account</p><div id="msg" class="auth-message"></div>${field('name','Full Name','Your full name')}${field('email','Email','you@example.com','email')}${field('password','Password','At least 6 characters','password')}${field('confirm','Confirm Password','Repeat password','password')}<button class="primary-btn full" id="regBtn">Register</button><button class="text-btn" id="loginBtn">Already have an account? Login</button></div></div>`
  const msg=document.getElementById('msg')!;const show=(t:string,e=false)=>{msg.textContent=t;msg.className=`auth-message ${e?'error':'success'}`};document.getElementById('loginBtn')!.onclick=login
  document.getElementById('regBtn')!.onclick=async()=>{
    const name=(document.getElementById('name') as HTMLInputElement).value.trim(),email=(document.getElementById('email') as HTMLInputElement).value.trim().toLowerCase(),password=(document.getElementById('password') as HTMLInputElement).value,confirm=(document.getElementById('confirm') as HTMLInputElement).value
    if(!name||!email||!password||!confirm)return show('Please fill in all fields.',true)
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return show('Please enter a valid email address.',true)
    if(password.length<6||password!==confirm)return show(password.length<6?'Password must be at least 6 characters.':'Passwords do not match.',true)
    const b=document.getElementById('regBtn') as HTMLButtonElement;b.disabled=true;b.textContent='Creating account...'
    try{const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:name},emailRedirectTo:location.origin}});if(error)return show(authErrorMessage(error),true);if(data.session)await dashboard();else show('Account created. Please confirm your email before logging in.')}catch(e){show(authErrorMessage(e),true)}finally{b.disabled=false;b.textContent='Register'}
  }
}
function forgotPassword(){
  if(!authGuard())return
  app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">E</div><h1>Reset Password</h1><p class="login-subtitle">We will send a secure reset link to your email.</p><div id="msg" class="auth-message"></div>${field('resetEmail','Email','you@example.com','email')}<button class="primary-btn full" id="resetBtn">Send Reset Link</button><button class="text-btn" id="backLogin">← Back to Login</button></div></div>`
  const msg=document.getElementById('msg')!;const show=(t:string,e=false)=>{msg.textContent=t;msg.className=`auth-message ${e?'error':'success'}`}
  document.getElementById('backLogin')!.onclick=login
  document.getElementById('resetBtn')!.onclick=async()=>{const email=(document.getElementById('resetEmail') as HTMLInputElement).value.trim().toLowerCase();if(!email)return show('Please enter your email.',true);const b=document.getElementById('resetBtn') as HTMLButtonElement;b.disabled=true;b.textContent='Sending...';try{const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin});show(error?authErrorMessage(error):'Reset link sent. Check your email inbox.')}catch(e){show(authErrorMessage(e),true)}finally{b.disabled=false;b.textContent='Send Reset Link'}}
}
function updatePasswordPage(){
  app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">E</div><h1>Set New Password</h1><p class="login-subtitle">Choose a new password for your account.</p><div id="msg" class="auth-message"></div>${field('newPassword','New Password','At least 6 characters','password')}${field('confirmNewPassword','Confirm Password','Repeat password','password')}<button class="primary-btn full" id="updatePasswordBtn">Update Password</button></div></div>`
  const msg=document.getElementById('msg')!;const show=(t:string,e=false)=>{msg.textContent=t;msg.className=`auth-message ${e?'error':'success'}`}
  document.getElementById('updatePasswordBtn')!.onclick=async()=>{const a=(document.getElementById('newPassword') as HTMLInputElement).value,bp=(document.getElementById('confirmNewPassword') as HTMLInputElement).value;if(a.length<6)return show('Password must be at least 6 characters.',true);if(a!==bp)return show('Passwords do not match.',true);const b=document.getElementById('updatePasswordBtn') as HTMLButtonElement;b.disabled=true;b.textContent='Updating...';try{const {error}=await supabase.auth.updateUser({password:a});if(error)return show(authErrorMessage(error),true);show('Password updated successfully. Redirecting...');setTimeout(()=>dashboard(),700)}catch(e){show(authErrorMessage(e),true)}finally{b.disabled=false;b.textContent='Update Password'}}
}

async function privatePhotoUrl(bucket:string,stored:string){
  if(!stored)return '';
  let path=stored;
  const marker=`/storage/v1/object/public/${bucket}/`;
  const idx=path.indexOf(marker);
  if(idx>=0)path=path.slice(idx+marker.length).split('?')[0];
  const {data,error}=await supabase.storage.from(bucket).createSignedUrl(path,60*60);
  if(error){console.error('Photo URL error',error);return ''}
  return data?.signedUrl||'';
}

async function loadStudents(){const c=await context();if(!c)return [];const {data,error}=await supabase.from('students').select('id,institute_id,user_id,student_id,full_name,phone,email,guardian_name,guardian_phone,address,date_of_birth,gender,admission_date,status,photo_url,created_at,updated_at').eq('institute_id',c.instituteId).order('created_at',{ascending:false});if(error){console.error(error);alert(`Student load failed: ${error.message}`);return []}studentsCache=await Promise.all((data||[]).map(async(r:any)=>({dbId:r.id,id:r.student_id||r.id,name:r.full_name||'',phone:r.phone||'',email:r.email||'',batch:'',fee:0,status:r.status||'active',dob:r.date_of_birth||'',gender:r.gender||'',guardian:r.guardian_name||'',guardianPhone:r.guardian_phone||'',address:r.address||'',admissionDate:r.admission_date||'',photoUrl:await privatePhotoUrl('student-photos',r.photo_url||''),photoPath:r.photo_url||''})));return studentsCache}
function studentCard(s:Student){return `<div class="student-card"><div class="student-avatar" style="overflow:hidden">${s.photoUrl?`<img src="${esc(s.photoUrl)}" alt="" style="width:100%;height:100%;object-fit:cover"/>`:initials(s.name)}</div><div class="student-info"><b>${esc(s.name)}</b><small>ID: ${esc(s.id)}</small><small>📞 ${esc(s.phone)}</small>${s.guardian?`<small>Guardian: ${esc(s.guardian)}</small>`:''}</div><span class="status ${s.status==='active'?'active':'inactive'}">${esc(s.status)}</span><button class="outline-btn" data-view="${esc(s.dbId)}">View</button><button class="outline-btn" data-edit="${esc(s.dbId)}">Edit</button><button class="danger-btn" data-toggle="${esc(s.dbId)}">${s.status==='active'?'Deactivate':'Activate'}</button></div>`}
function studentDetails(s:Student){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Student Profile</h1><p>Complete student information</p></div><button class="outline-btn" data-page="students">← Back</button></div><div class="content-card"><div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap"><div class="student-avatar" style="width:100px;height:100px;overflow:hidden;font-size:30px">${s.photoUrl?`<img src="${esc(s.photoUrl)}" alt="Student photo" style="width:100%;height:100%;object-fit:cover"/>`:initials(s.name)}</div><div><h2 style="margin:0 0 6px">${esc(s.name)}</h2><p style="margin:0">Student ID: <b>${esc(s.id)}</b></p><p style="margin:4px 0">Status: <span class="status ${s.status==='active'?'active':'inactive'}">${esc(s.status)}</span></p></div></div><hr style="margin:22px 0;border:0;border-top:1px solid #e5e7eb"><div class="form-grid"><div><b>Phone</b><p>${esc(s.phone||'—')}</p></div><div><b>Email</b><p>${esc(s.email||'—')}</p></div><div><b>Date of Birth</b><p>${esc(s.dob||'—')}</p></div><div><b>Gender</b><p>${esc(s.gender||'—')}</p></div><div><b>Guardian</b><p>${esc(s.guardian||'—')}</p></div><div><b>Guardian Phone</b><p>${esc(s.guardianPhone||'—')}</p></div><div><b>Admission Date</b><p>${esc(s.admissionDate||'—')}</p></div><div class="full-width"><b>Address</b><p>${esc(s.address||'—')}</p></div></div><div class="form-actions"><button class="outline-btn" data-edit="${esc(s.dbId)}">Edit Student</button></div></div></main>`;bind();document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>editStudent((b as HTMLElement).dataset.edit!)))}
async function studentsPage(){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Students</h1><p>Real student records from Supabase</p></div><button class="primary-btn" data-page="add">+ Add Student</button></div><div class="content-card"><div class="toolbar"><input id="search" class="search-input" placeholder="Search name, ID, phone or guardian..."/><select id="statusFilter"><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="left">Left</option></select></div><div id="studentCount" class="student-list-header">Loading...</div><div id="list" class="students-list"></div></div></main>`;bind();await loadStudents();renderStudentList();document.getElementById('search')!.addEventListener('input',renderStudentList);document.getElementById('statusFilter')!.addEventListener('change',renderStudentList)}
function renderStudentList(){const q=(document.getElementById('search') as HTMLInputElement)?.value.toLowerCase()||'',f=(document.getElementById('statusFilter') as HTMLSelectElement)?.value||'all';const list=studentsCache.filter(s=>(f==='all'||s.status===f)&&[s.name,s.id,s.phone,s.guardian].join(' ').toLowerCase().includes(q));const count=document.getElementById('studentCount');if(count)count.innerHTML=`<b>${list.length} Students</b><span>${studentsCache.filter(s=>s.status==='active').length} active</span>`;const box=document.getElementById('list');if(box)box.innerHTML=list.length?list.map(studentCard).join(''):`<div class="empty-state"><div class="big-icon">👨‍🎓</div><h3>No students found</h3><p>Add your first student to begin.</p></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const x=studentsCache.find(s=>s.dbId===(b as HTMLElement).dataset.view);if(x)studentDetails(x)}));document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>editStudent((b as HTMLElement).dataset.edit!)));document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>toggleStudent((b as HTMLElement).dataset.toggle!)))}
async function toggleStudent(id:string){const s=studentsCache.find(x=>x.dbId===id);if(!s)return;const next=s.status==='active'?'inactive':'active';if(!confirm(`${next==='inactive'?'Deactivate':'Activate'} ${s.name}?`))return;const {error}=await supabase.from('students').update({status:next,updated_at:new Date().toISOString()}).eq('id',id);if(error)return alert(`Update failed: ${error.message}`);await studentsPage()}
function studentForm(s?:Student){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${s?'Edit Student':'Add New Student'}</h1><p>${s?'Update the student record':'Create a real student record in Supabase'}</p></div></div><div class="content-card"><h2>Student Information</h2><div class="form-grid">${field('studentName','Student Name *','Enter student name','text',s?.name||'')}${field('studentPhone','Phone Number *','01XXXXXXXXX','text',s?.phone||'')}${field('studentEmail','Email','student@email.com','email',s?.email||'')}${field('studentDob','Date of Birth','','date',s?.dob||'')}${select('studentGender','Gender',['Male','Female','Other'],s?.gender||'')}${field('guardianName','Guardian Name *','Enter guardian name','text',s?.guardian||'')}${field('guardianPhone','Guardian Phone *','01XXXXXXXXX','text',s?.guardianPhone||'')}${field('address','Address','Enter address','text',s?.address||'')}${field('admissionDate','Admission Date *','','date',s?.admissionDate||today())}<div class="form-group"><label>Student Photo</label><input id="studentPhoto" type="file" accept="image/jpeg,image/png,image/webp"/><small>JPG, PNG or WebP · optional · max 2 MB</small>${s?.photoUrl?`<img id="studentPhotoPreview" src="${esc(s.photoUrl)}" alt="Current photo" style="width:72px;height:72px;border-radius:14px;object-fit:cover;margin-top:8px"/>`:`<img id="studentPhotoPreview" alt="Photo preview" style="display:none;width:72px;height:72px;border-radius:14px;object-fit:cover;margin-top:8px"/>`}</div></div><div class="form-actions"><button class="outline-btn" data-page="students">Cancel</button><button class="primary-btn" id="saveStudent">${s?'Update Student':'Save Student'}</button></div></div></main>`;bind();document.getElementById('studentPhoto')?.addEventListener('change',()=>{const input=document.getElementById('studentPhoto') as HTMLInputElement;const file=input.files?.[0];const preview=document.getElementById('studentPhotoPreview') as HTMLImageElement|null;if(file&&preview){preview.src=URL.createObjectURL(file);preview.style.display='block'}});document.getElementById('saveStudent')!.onclick=()=>saveStudent(s)}
async function saveStudent(existing?:Student){const v=(id:string)=>(document.getElementById(id) as HTMLInputElement).value.trim(),g=(document.getElementById('studentGender') as HTMLSelectElement).value;const name=v('studentName'),phone=v('studentPhone'),guardian=v('guardianName'),guardianPhone=v('guardianPhone'),admission=v('admissionDate');if(!name||!phone||!guardian||!guardianPhone||!admission)return alert('Please fill all required fields.');const c=await context();if(!c)return alert('Could not find your institute. Please log in again.');let photoUrl=existing?.photoPath||null;const file=(document.getElementById('studentPhoto') as HTMLInputElement)?.files?.[0];if(file){if(file.size>2*1024*1024)return alert('Photo must be 2 MB or smaller.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return alert('Please choose a JPG, PNG or WebP image.');const ext=file.type.split('/')[1].replace('jpeg','jpg');const path=`${c.instituteId}/${existing?.dbId||crypto.randomUUID()}.${ext}`;const up=await supabase.storage.from('student-photos').upload(path,file,{upsert:true,contentType:file.type});if(up.error)return alert(`Photo upload failed: ${up.error.message}`);photoUrl=path}const payload={full_name:name,phone,email:v('studentEmail')||null,guardian_name:guardian,guardian_phone:guardianPhone,address:v('address')||null,date_of_birth:v('studentDob')||null,gender:g||null,admission_date:admission,status:existing?.status||'active',institute_id:c.instituteId,photo_url:photoUrl};let error:any;if(existing){({error}=await supabase.from('students').update(payload).eq('id',existing.dbId))}else{({error}=await supabase.from('students').insert({...payload,student_id:`EL-${Date.now()}`,user_id:null}))}if(error)return alert(`Student save failed: ${error.message}`);alert(existing?'Student updated successfully!':'Student added successfully!');await studentsPage()}
async function editStudent(id:string){const s=studentsCache.find(x=>x.dbId===id);if(s)studentForm(s)}


type Course={id:string;name:string;description:string;duration:string;fee:number;status:string}
let coursesCache:Course[]=[]

async function loadCourses(){
  const c=await context(); if(!c)return []
  const {data,error}=await supabase.from('courses').select('*').eq('institute_id',c.instituteId).order('created_at',{ascending:false})
  if(error){console.error(error);alert(`Course load failed: ${error.message}`);return []}
  coursesCache=(data||[]).map((r:any)=>({id:r.id,name:r.name||'',description:r.notes||'',duration:r.duration||'',fee:Number(r.fee||0),status:r.status||'active'}))
  return coursesCache
}
function courseCard(c:Course){return `<div class="student-card"><div class="student-avatar">${initials(c.name)}</div><div class="student-info"><b>${esc(c.name)}</b><small>${esc(c.duration||'Duration not set')}</small><small>৳ ${c.fee.toLocaleString()}</small></div><span class="status ${c.status==='active'?'active':'inactive'}">${esc(c.status)}</span><button class="outline-btn" data-course-edit="${esc(c.id)}">Edit</button><button class="danger-btn" data-course-toggle="${esc(c.id)}">${c.status==='active'?'Deactivate':'Activate'}</button></div>`}
async function coursesPage(){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Courses</h1><p>Manage course definitions, fees and availability.</p></div><button class="primary-btn" data-course-add>+ Add Course</button></div><div class="content-card"><div class="toolbar"><input id="courseSearch" class="search-input" placeholder="Search course, duration or description..."/><select id="courseStatusFilter"><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div id="courseCount" class="student-list-header">Loading...</div><div id="courseList" class="students-list"></div></div></main>`;bind();document.querySelector('[data-course-add]')?.addEventListener('click',()=>courseForm());await loadCourses();renderCourses();document.getElementById('courseSearch')?.addEventListener('input',renderCourses);document.getElementById('courseStatusFilter')?.addEventListener('change',renderCourses)}
function renderCourses(){const q=((document.getElementById('courseSearch') as HTMLInputElement)?.value||'').toLowerCase(),f=(document.getElementById('courseStatusFilter') as HTMLSelectElement)?.value||'all';const list=coursesCache.filter(c=>(f==='all'||c.status===f)&&[c.name,c.duration,c.description].join(' ').toLowerCase().includes(q));const count=document.getElementById('courseCount');if(count)count.innerHTML=`<b>${list.length} Courses</b><span>${coursesCache.filter(x=>x.status==='active').length} active · ${coursesCache.filter(x=>x.status!=='active').length} inactive</span>`;const box=document.getElementById('courseList');if(box)box.innerHTML=list.length?list.map(courseCard).join(''):`<div class="empty-state"><div class="big-icon">📚</div><h3>No courses found</h3><p>${q||f!=='all'?'Try another search or filter.':'Create your first course.'}</p></div>`;document.querySelectorAll('[data-course-edit]').forEach(b=>b.addEventListener('click',()=>courseForm(coursesCache.find(x=>x.id===(b as HTMLElement).dataset.courseEdit))));document.querySelectorAll('[data-course-toggle]').forEach(b=>b.addEventListener('click',()=>toggleCourse((b as HTMLElement).dataset.courseToggle!)))}
function courseForm(existing?:Course){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${existing?'Edit Course':'Add Course'}</h1><p>Course settings are stored in Supabase.</p></div></div><div class="content-card"><div class="form-grid">${field('courseName','Course Name *','e.g. Spoken English','text',existing?.name||'')}${field('courseDuration','Duration','e.g. 3 months','text',existing?.duration||'')}${field('courseFee','Course Fee (৳)','0','number',String(existing?.fee||0))}${select('courseStatus','Status',['active','inactive'],existing?.status||'active')}</div>${field('courseDescription','Description','Optional description','text',existing?.description||'')}<div class="form-actions"><button class="outline-btn" data-page="courses">Cancel</button><button class="primary-btn" id="saveCourse">${existing?'Update Course':'Save Course'}</button></div></div></main>`;bind();document.getElementById('saveCourse')!.onclick=async()=>{const c=await context();if(!c)return alert('Could not find your institute. Please log in again.');const name=(document.getElementById('courseName') as HTMLInputElement).value.trim();if(!name)return alert('Course name is required.');const fee=Number((document.getElementById('courseFee') as HTMLInputElement).value||0);if(!Number.isFinite(fee)||fee<0)return alert('Course fee cannot be negative.');const payload={institute_id:c.instituteId,name,description:(document.getElementById('courseDescription') as HTMLInputElement).value.trim()||null,duration:(document.getElementById('courseDuration') as HTMLInputElement).value.trim()||null,fee,status:(document.getElementById('courseStatus') as HTMLSelectElement).value,updated_at:new Date().toISOString()};let error:any;if(existing)({error}=await supabase.from('courses').update(payload).eq('id',existing.id));else({error}=await supabase.from('courses').insert(payload));if(error)return alert(`Course save failed: ${error.message}`);await coursesPage()}}
async function toggleCourse(id:string){const c=coursesCache.find(x=>x.id===id);if(!c)return;const next=c.status==='active'?'inactive':'active';if(!confirm(`${next==='inactive'?'Deactivate':'Activate'} ${c.name}?`))return;const {error}=await supabase.from('courses').update({status:next,updated_at:new Date().toISOString()}).eq('id',id);if(error)return alert(`Update failed: ${error.message}`);await coursesPage()}

type Batch={id:string;name:string;courseId:string;courseName:string;teacherId:string;teacherName:string;room:string;startDate:string;endDate:string;fee:number;status:string}
let batchesCache:Batch[]=[]
let teachersCache:any[]=[]
let studentsForBatch:any[]=[]

async function loadBatchLookups(){
  const c=await context();if(!c)return
  const [cr,tr,sr]=await Promise.all([
    supabase.from('courses').select('id,name,fee,status').eq('institute_id',c.instituteId).eq('status','active').order('name'),
    supabase.from('teachers').select('id,name,status').eq('institute_id',c.instituteId).order('name'),
    supabase.from('students').select('id,student_id,full_name,status').eq('institute_id',c.instituteId).eq('status','active').order('full_name')
  ])
  if(cr.error)console.error(cr.error)
  if(tr.error)console.error(tr.error)
  if(sr.error)console.error(sr.error)
  coursesCache=(cr.data||[]).map((r:any)=>({id:r.id,name:r.name||'',description:'',duration:'',fee:Number(r.fee||0),status:r.status||'active'}))
  teachersCache=tr.data||[]
  studentsForBatch=sr.data||[]
}
async function loadBatches(){
  const c=await context();if(!c)return []
  const {data,error}=await supabase.from('batches').select('id,institute_id,course_id,teacher_id,name,room,start_date,end_date,fee,status,created_at').eq('institute_id',c.instituteId).order('created_at',{ascending:false})
  if(error){console.error(error);alert(`Batch load failed: ${error.message}`);return []}
  const courseMap=new Map(coursesCache.map(x=>[x.id,x.name]))
  const teacherMap=new Map(teachersCache.map(x=>[x.id,x.name||'']))
  batchesCache=(data||[]).map((r:any)=>({id:r.id,name:r.name||'',courseId:r.course_id||'',courseName:courseMap.get(r.course_id)||'Unknown course',teacherId:r.teacher_id||'',teacherName:teacherMap.get(r.teacher_id)||'Unassigned',room:r.room||'',startDate:r.start_date||'',endDate:r.end_date||'',fee:Number(r.fee||0),status:r.status||'active'}))
  return batchesCache
}
function batchCard(b:Batch){return `<div class="student-card"><div class="student-avatar">${initials(b.name)}</div><div class="student-info"><b>${esc(b.name)}</b><small>Course: ${esc(b.courseName)}</small><small>Teacher: ${esc(b.teacherName)}</small><small>${b.startDate||'No start date'}${b.endDate?' → '+b.endDate:''} ${b.room?'• Room '+esc(b.room):''}</small><small>Fee: ৳ ${b.fee.toLocaleString()}</small></div><span class="status ${b.status==='active'?'active':'inactive'}">${esc(b.status)}</span><button class="outline-btn" data-batch-students="${esc(b.id)}">Students</button><button class="outline-btn" data-batch-edit="${esc(b.id)}">Edit</button><button class="danger-btn" data-batch-toggle="${esc(b.id)}">${b.status==='active'?'Deactivate':'Activate'}</button></div>`}
async function batchesPage(){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Batches</h1><p>Manage courses, teachers, schedules and batch fees.</p></div><button class="primary-btn" data-batch-add>+ Add Batch</button></div><div class="content-card"><div class="toolbar"><input id="batchSearch" class="search-input" placeholder="Search batch, course or teacher..."/><select id="batchStatus"><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div id="batchCount" class="student-list-header">Loading...</div><div id="batchList" class="students-list"></div></div></main>`;bind();document.querySelector('[data-batch-add]')?.addEventListener('click',()=>batchForm());await loadBatchLookups();await loadBatches();renderBatches();document.getElementById('batchSearch')?.addEventListener('input',renderBatches);document.getElementById('batchStatus')?.addEventListener('change',renderBatches)}
function renderBatches(){const q=(document.getElementById('batchSearch') as HTMLInputElement)?.value.toLowerCase()||'',f=(document.getElementById('batchStatus') as HTMLSelectElement)?.value||'all';const list=batchesCache.filter(b=>(f==='all'||b.status===f)&&[b.name,b.courseName,b.teacherName,b.room].join(' ').toLowerCase().includes(q));const c=document.getElementById('batchCount');if(c)c.innerHTML=`<b>${list.length} Batches</b><span>${batchesCache.filter(x=>x.status==='active').length} active</span>`;const box=document.getElementById('batchList');if(box)box.innerHTML=list.length?list.map(batchCard).join(''):`<div class="empty-state"><div class="big-icon">📚</div><h3>No batches found</h3><p>Create a batch after adding a course.</p></div>`;document.querySelectorAll('[data-batch-students]').forEach(b=>b.addEventListener('click',()=>batchStudentsPage((b as HTMLElement).dataset.batchStudents!)));document.querySelectorAll('[data-batch-edit]').forEach(b=>b.addEventListener('click',()=>batchForm(batchesCache.find(x=>x.id===(b as HTMLElement).dataset.batchEdit))));document.querySelectorAll('[data-batch-toggle]').forEach(b=>b.addEventListener('click',()=>toggleBatch((b as HTMLElement).dataset.batchToggle!)))}
function batchForm(existing?:Batch){
  const courseOpts=coursesCache.map(x=>`<option value="${esc(x.id)}" ${x.id===existing?.courseId?'selected':''}>${esc(x.name)} — ৳ ${x.fee.toLocaleString()}</option>`).join('')
  const teacherOpts=(teachersCache as any[]).map((x:any)=>`<option value="${esc(x.id)}" ${x.id===existing?.teacherId?'selected':''}>${esc(x.name||'Unnamed teacher')}</option>`).join('')
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${existing?'Edit Batch':'Add Batch'}</h1><p>Connect this batch to a course and teacher.</p></div></div><div class="content-card"><div class="form-grid">${field('batchName','Batch Name *','e.g. Morning Spoken English','text',existing?.name||'')}<div class="form-group"><label>Course *</label><select id="batchCourse"><option value="">Select course</option>${courseOpts}</select></div><div class="form-group"><label>Teacher</label><select id="batchTeacher"><option value="">Unassigned</option>${teacherOpts}</select></div>${field('batchRoom','Room','e.g. Room 201','text',existing?.room||'')}${field('batchStart','Start Date *','','date',existing?.startDate||today())}${field('batchEnd','End Date','','date',existing?.endDate||'')}${field('batchFee','Batch Fee (৳)','0','number',String(existing?.fee||0))}${select('batchStatus','Status',['active','inactive'],existing?.status||'active')}</div><div class="form-actions"><button class="outline-btn" data-page="batches">Cancel</button><button class="primary-btn" id="saveBatch">${existing?'Update Batch':'Save Batch'}</button></div></div></main>`;bind();document.getElementById('saveBatch')!.onclick=async()=>{const c=await context();if(!c)return alert('Could not find your institute. Please log in again.');const v=(id:string)=>(document.getElementById(id) as HTMLInputElement).value.trim();const name=v('batchName'),courseId=(document.getElementById('batchCourse') as HTMLSelectElement).value;if(!name||!courseId)return alert('Batch name and course are required.');const fee=Number(v('batchFee')||0);if(fee<0)return alert('Fee cannot be negative.');const payload={institute_id:c.instituteId,name,course_id:courseId,teacher_id:(document.getElementById('batchTeacher') as HTMLSelectElement).value||null,room:v('batchRoom')||null,start_date:v('batchStart')||null,end_date:v('batchEnd')||null,fee,status:(document.getElementById('batchStatus') as HTMLSelectElement).value,updated_at:new Date().toISOString()};let error:any;if(existing)({error}=await supabase.from('batches').update(payload).eq('id',existing.id));else({error}=await supabase.from('batches').insert(payload));if(error)return alert(`Batch save failed: ${error.message}`);await batchesPage()}}
async function batchStudentsPage(batchId:string){
  const c=await context();if(!c)return
  const batch=batchesCache.find(x=>x.id===batchId);if(!batch)return
  const {data:assigned,error:ae}=await supabase.from('batch_students').select('student_id').eq('institute_id',c.instituteId).eq('batch_id',batchId)
  if(ae)return alert(`Student assignment load failed: ${ae.message}`)
  const assignedIds=new Set((assigned||[]).map((x:any)=>x.student_id))
  const {data:allStudents,error:se}=await supabase.from('students').select('id,student_id,full_name,phone,status').eq('institute_id',c.instituteId).order('full_name')
  if(se)return alert(`Student list load failed: ${se.message}`)
  const rows=(allStudents||[]).map((st:any)=>`<label class="form-check"><input type="checkbox" data-student-check="${esc(st.id)}" ${assignedIds.has(st.id)?'checked':''}/><span><b>${esc(st.full_name||'Unnamed')}</b><small>${esc(st.student_id||'')} ${st.phone?'• '+esc(st.phone):''}</small></span></label>`).join('')
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Batch Students</h1><p>${esc(batch.name)} • ${esc(batch.courseName)}</p></div><button class="outline-btn" data-page="batches">Back to Batches</button></div><div class="content-card"><div class="student-list-header"><b>${(assigned||[]).length} assigned</b><span>Select students and save</span></div><div id="batchStudentRows" class="check-list">${rows||'<div class="empty-state"><h3>No students yet</h3><p>Add students first, then assign them to this batch.</p></div>'}</div><div class="form-actions"><button class="primary-btn" id="saveBatchStudents">Save Assignment</button></div></div></main>`
  bind()
  document.getElementById('saveBatchStudents')!.addEventListener('click',async()=>{
    const selected=Array.from(document.querySelectorAll('[data-student-check]:checked')).map(x=>(x as HTMLInputElement).dataset.studentCheck!).filter(Boolean)
    const current=Array.from(assignedIds) as string[]
    const toAdd=selected.filter(id=>!assignedIds.has(id));const toRemove=current.filter(id=>!selected.includes(id))
    const adds=toAdd.map(student_id=>({institute_id:c.instituteId,batch_id:batchId,student_id}))
    if(adds.length){const {error}=await supabase.from('batch_students').insert(adds);if(error)return alert(`Assignment save failed: ${error.message}`)}
    if(toRemove.length){const {error}=await supabase.from('batch_students').delete().eq('institute_id',c.instituteId).eq('batch_id',batchId).in('student_id',toRemove);if(error)return alert(`Assignment removal failed: ${error.message}`)}
    alert('Batch student assignment saved.');await batchStudentsPage(batchId)
  })
}


type Fee={id:string;studentId:string;studentName:string;studentCode:string;feeType:string;amount:number;discount:number;dueAmount:number;dueDate:string;status:string;paid:number}
type Payment={id:string;feeId:string;studentId:string;amount:number;method:string;reference:string;receipt:string;paidAt:string}
let feesCache:Fee[]=[]
let paymentsCache:Payment[]=[]
let feeStudents:any[]=[]

async function loadFees(){
  const c=await context(); if(!c)return []
  const [fr,sr,pr]=await Promise.all([
    supabase.from('fees').select('id,student_id,fee_type,amount,discount,due_amount,due_date,status,created_at').eq('institute_id',c.instituteId).order('due_date',{ascending:false}),
    supabase.from('students').select('id,student_id,full_name,status').eq('institute_id',c.instituteId).order('full_name'),
    supabase.from('fee_payments').select('id,fee_id,student_id,amount,payment_method,transaction_id,payment_date,receipt_number').eq('institute_id',c.instituteId).order('payment_date',{ascending:false})
  ])
  if(fr.error){alert(`Fee load failed: ${fr.error.message}`);return []}
  if(pr.error){alert(`Payment load failed: ${pr.error.message}`);return []}
  feeStudents=sr.data||[]
  const studentMap=new Map(feeStudents.map(x=>[x.id,x]))
  paymentsCache=(pr.data||[]).map((r:any)=>({id:r.id,feeId:r.fee_id||'',studentId:r.student_id||'',amount:Number(r.amount||0),method:r.payment_method||'',reference:r.transaction_id||'',receipt:r.receipt_number||'',paidAt:r.payment_date||''}))
  const paidMap=new Map<string,number>()
  paymentsCache.forEach(p=>paidMap.set(p.feeId,(paidMap.get(p.feeId)||0)+p.amount))
  feesCache=(fr.data||[]).map((r:any)=>{const amount=Number(r.amount||0),discount=Number(r.discount||0),base=Math.max(0,amount-discount),paid=paidMap.get(r.id)||0;const due=Math.max(0,base-paid);const status=due<=0?'paid':paid>0?'partial':'due';const st=studentMap.get(r.student_id)||{};return {id:r.id,studentId:r.student_id||'',studentName:st.full_name||'Unknown student',studentCode:st.student_id||'',feeType:r.fee_type||'Fee',amount,discount,dueAmount:due,dueDate:r.due_date||'',status,paid}})
  return feesCache
}
function feeCard(f:Fee){return `<div class="student-card"><div class="student-avatar">${initials(f.studentName)}</div><div class="student-info"><b>${esc(f.studentName)}</b><small>${esc(f.studentCode)} • ${esc(f.feeType)}</small><small>Total: ৳ ${Math.max(0,f.amount-f.discount).toLocaleString()} • Paid: ৳ ${f.paid.toLocaleString()}</small><small>Due date: ${esc(f.dueDate||'Not set')}</small></div><span class="status ${f.status==='paid'?'active':f.status==='partial'?'inactive':'left'}">${esc(f.status)}</span><div class="student-fee"><b>৳ ${f.dueAmount.toLocaleString()}</b><small>Due</small></div>${f.dueAmount>0?`<button class="primary-btn" data-pay-fee="${esc(f.id)}">Pay</button>`:''}<button class="outline-btn" data-fee-history="${esc(f.id)}">History</button></div>`}
async function feesPage(){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Fees & Payments</h1><p>Fee setup, paid/due tracking and payment history.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="outline-btn" data-payment-history>Payment History</button><button class="outline-btn" data-fee-monthly>Generate Monthly Fees</button><button class="primary-btn" data-fee-add>+ Add Fee</button></div></div><div class="content-card"><div class="fee-overview"><div><span>Total billed</span><b id="feeTotal">৳ 0</b></div><div><span>Collected</span><b id="feePaid">৳ 0</b></div><div><span>Due</span><b id="feeDue">৳ 0</b></div></div><div class="toolbar"><input id="feeSearch" class="search-input" placeholder="Search student, ID or fee type..."/><select id="feeStatus"><option value="all">All</option><option value="due">Due</option><option value="partial">Partial</option><option value="paid">Paid</option></select></div><div id="feeCount" class="student-list-header">Loading...</div><div id="feeList" class="students-list"></div></div></main>`;bind();document.querySelector('[data-fee-add]')?.addEventListener('click',()=>feeForm());document.querySelector('[data-fee-monthly]')?.addEventListener('click',()=>monthlyFeeForm());document.querySelector('[data-payment-history]')?.addEventListener('click',()=>allPaymentHistoryPage());await loadFees();renderFees();document.getElementById('feeSearch')?.addEventListener('input',renderFees);document.getElementById('feeStatus')?.addEventListener('change',renderFees)}
function allPaymentHistoryPage(){const q0='', rows=paymentsCache.map(p=>{const f=feesCache.find(x=>x.id===p.feeId);return f?{p,f}:null}).filter(Boolean) as {p:Payment;f:Fee}[];app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Payment History</h1><p>All payment collections with printable receipts.</p></div><button class="outline-btn" data-page="fees">← Back to Fees</button></div><div class="content-card"><div class="toolbar"><input id="paymentHistorySearch" class="search-input" placeholder="Search student, receipt, reference or method..."/><select id="paymentMethodFilter"><option value="all">All methods</option><option>Cash</option><option>bKash</option><option>Nagad</option><option>Rocket</option><option>Bank</option></select></div><div id="paymentHistoryList" class="students-list"></div></div></main>`;bind();const render=()=>{const q=(document.getElementById('paymentHistorySearch') as HTMLInputElement)?.value.toLowerCase()||q0,m=(document.getElementById('paymentMethodFilter') as HTMLSelectElement)?.value||'all';const list=rows.filter(({p,f})=>(m==='all'||p.method===m)&&[f.studentName,f.studentCode,f.feeType,p.receipt,p.reference,p.method].join(' ').toLowerCase().includes(q));const box=document.getElementById('paymentHistoryList');if(box)box.innerHTML=list.length?list.map(({p,f})=>`<div class="history"><b>৳ ${p.amount.toLocaleString()}</b><span>${esc(p.method)}</span><small>${esc(f.studentName)} • ${esc(f.studentCode)} • ${esc(f.feeType)}<br>${p.paidAt?new Date(p.paidAt).toLocaleString():'—'}${p.receipt?' • Receipt '+esc(p.receipt):''}${p.reference?' • Ref '+esc(p.reference):''}</small><button class="outline-btn" data-print-receipt="${esc(p.id)}">Print Receipt</button></div>`).join(''):`<div class="empty-state"><h3>No payment records found</h3></div>`;document.querySelectorAll('[data-print-receipt]').forEach(b=>b.addEventListener('click',()=>printReceipt((b as HTMLElement).dataset.printReceipt!)))};render();document.getElementById('paymentHistorySearch')?.addEventListener('input',render);document.getElementById('paymentMethodFilter')?.addEventListener('change',render)}
function renderFees(){const q=(document.getElementById('feeSearch') as HTMLInputElement)?.value.toLowerCase()||'',f=(document.getElementById('feeStatus') as HTMLSelectElement)?.value||'all';const list=feesCache.filter(x=>(f==='all'||x.status===f)&&[x.studentName,x.studentCode,x.feeType].join(' ').toLowerCase().includes(q));const total=feesCache.reduce((a,x)=>a+Math.max(0,x.amount-x.discount),0),paid=feesCache.reduce((a,x)=>a+x.paid,0),due=feesCache.reduce((a,x)=>a+x.dueAmount,0);const t=document.getElementById('feeTotal');const p=document.getElementById('feePaid');const d=document.getElementById('feeDue');if(t)t.textContent=`৳ ${total.toLocaleString()}`;if(p)p.textContent=`৳ ${paid.toLocaleString()}`;if(d)d.textContent=`৳ ${due.toLocaleString()}`;const c=document.getElementById('feeCount');if(c)c.innerHTML=`<b>${list.length} Fee records</b><span>${feesCache.filter(x=>x.status==='due').length} due</span>`;const box=document.getElementById('feeList');if(box)box.innerHTML=list.length?list.map(feeCard).join(''):`<div class="empty-state"><div class="big-icon">💰</div><h3>No fee records</h3><p>Add a fee for a student to start tracking payments.</p></div>`;document.querySelectorAll('[data-pay-fee]').forEach(b=>b.addEventListener('click',()=>paymentForm((b as HTMLElement).dataset.payFee!)));document.querySelectorAll('[data-fee-history]').forEach(b=>b.addEventListener('click',()=>feeHistory((b as HTMLElement).dataset.feeHistory!)))}
async function monthlyFeeForm(){
  const c=await context();if(!c)return;
  const [br,cr]=await Promise.all([supabase.from('batches').select('id,name,course_id,status,fee').eq('institute_id',c.instituteId).eq('status','active').order('name'),supabase.from('courses').select('id,name').eq('institute_id',c.instituteId).order('name')]);
  if(br.error)return alert(`Batch load failed: ${br.error.message}`);
  const cm=new Map((cr.data||[]).map((x:any)=>[x.id,x.name]));
  const opts=(br.data||[]).map((b:any)=>`<option value="${esc(b.id)}">${esc(b.name)}${cm.get(b.course_id)?' — '+esc(cm.get(b.course_id)):''} · ৳${Number(b.fee||0).toLocaleString()}</option>`).join('');
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Generate Monthly Fees</h1><p>Create one monthly fee for every active student assigned to a batch.</p></div></div><div class="content-card"><div class="form-grid">${field('billingMonth','Billing Month *','','month',today().slice(0,7))}<div class="form-group"><label>Batch *</label><select id="monthlyBatch"><option value="">Select batch</option>${opts}</select></div>${field('monthlyType','Fee Type *','Monthly tuition')}${field('monthlyAmount','Amount (৳) *','0','number')}${field('monthlyDueDate','Due Date','','date',today())}</div><div class="notice-box"><b>Duplicate protection</b><p>Students who already have the same fee type for the selected month will be skipped.</p></div><div class="form-actions"><button class="outline-btn" data-page="fees">Cancel</button><button class="primary-btn" id="generateMonthly">Generate Fees</button></div></div></main>`;bind();
  const batchSel=document.getElementById('monthlyBatch') as HTMLSelectElement, amount=document.getElementById('monthlyAmount') as HTMLInputElement;
  batchSel.addEventListener('change',()=>{const b=(br.data||[]).find((x:any)=>x.id===batchSel.value);if(b&&Number(b.fee)>0)amount.value=String(b.fee)});
  document.getElementById('generateMonthly')!.onclick=async()=>{const batchId=batchSel.value,month=(document.getElementById('billingMonth') as HTMLInputElement).value,type=(document.getElementById('monthlyType') as HTMLInputElement).value.trim(),feeAmount=Number(amount.value||0),dueDate=(document.getElementById('monthlyDueDate') as HTMLInputElement).value;if(!batchId||!month||!type||feeAmount<=0)return alert('Please enter all required monthly fee details.');const bs=await supabase.from('batch_students').select('student_id').eq('institute_id',c.instituteId).eq('batch_id',batchId);if(bs.error)return alert(`Assignment load failed: ${bs.error.message}`);const ids=[...new Set((bs.data||[]).map((x:any)=>x.student_id).filter(Boolean))];if(!ids.length)return alert('No students are assigned to this batch.');const sr=await supabase.from('students').select('id,status').eq('institute_id',c.instituteId).eq('status','active').in('id',ids);if(sr.error)return alert(`Student load failed: ${sr.error.message}`);const activeIds=(sr.data||[]).map((x:any)=>x.id);const er=await supabase.from('fees').select('student_id').eq('institute_id',c.instituteId).eq('fee_type',type).eq('billing_month',`${month}-01`).in('student_id',activeIds);if(er.error)return alert(`Existing fee check failed: ${er.error.message}`);const existingIds=new Set((er.data||[]).map((x:any)=>x.student_id));const rows=activeIds.filter((id:string)=>!existingIds.has(id)).map((student_id:string)=>({institute_id:c.instituteId,student_id,fee_type:type,amount:feeAmount,discount:0,due_amount:feeAmount,due_date:dueDate||null,status:'unpaid',billing_month:`${month}-01`}));if(!rows.length)return alert('No new fees generated. All selected students already have this monthly fee.');const ins=await supabase.from('fees').insert(rows);if(ins.error)return alert(`Monthly fee generation failed: ${ins.error.message}`);alert(`Monthly fees generated: ${rows.length}\nSkipped existing: ${existingIds.size}`);await feesPage()};
}

function feeForm(){const opts=feeStudents.filter(s=>s.status==='active').map(s=>`<option value="${esc(s.id)}">${esc(s.full_name)} — ${esc(s.student_id||'')}</option>`).join('');app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Add Fee</h1><p>Create a fee record for a student.</p></div></div><div class="content-card"><div class="form-grid"><div class="form-group"><label>Student *</label><select id="feeStudent"><option value="">Select student</option>${opts}</select></div>${field('feeType','Fee Type *','Monthly tuition / Admission / Exam')}${field('feeAmount','Amount (৳) *','0','number')}${field('feeDiscount','Discount (৳)','0','number')}${field('feeDueDate','Due Date','','date',today())}</div><div class="form-actions"><button class="outline-btn" data-page="fees">Cancel</button><button class="primary-btn" id="saveFee">Save Fee</button></div></div></main>`;bind();document.getElementById('saveFee')!.onclick=async()=>{const c=await context();if(!c)return alert('Please log in again.');const student=(document.getElementById('feeStudent') as HTMLSelectElement).value,type=(document.getElementById('feeType') as HTMLInputElement).value.trim(),amount=Number((document.getElementById('feeAmount') as HTMLInputElement).value||0),discount=Number((document.getElementById('feeDiscount') as HTMLInputElement).value||0),dueDate=(document.getElementById('feeDueDate') as HTMLInputElement).value;if(!student||!type||amount<=0||discount<0||discount>amount)return alert('Please enter valid fee details.');const {error}=await supabase.from('fees').insert({institute_id:c.instituteId,student_id:student,fee_type:type,amount,discount,due_amount:amount-discount,due_date:dueDate||null,status:'unpaid'});if(error)return alert(`Fee save failed: ${error.message}`);await feesPage()}}
function paymentForm(feeId:string){const f=feesCache.find(x=>x.id===feeId);if(!f)return;app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Record Payment</h1><p>${esc(f.studentName)} • ${esc(f.feeType)} • Due ৳ ${f.dueAmount.toLocaleString()}</p></div></div><div class="content-card"><div class="form-grid">${field('payAmount','Payment Amount (৳) *',String(f.dueAmount),'number')}${select('payMethod','Payment Method',['Cash','bKash','Nagad','Rocket','Bank'],'Cash')}${field('payRef','Transaction Reference','Optional')}</div><div class="form-actions"><button class="outline-btn" data-page="fees">Cancel</button><button class="primary-btn" id="savePayment">Save Payment</button></div></div></main>`;bind();document.getElementById('savePayment')!.onclick=async()=>{const c=await context();if(!c)return alert('Please log in again.');const amount=Number((document.getElementById('payAmount') as HTMLInputElement).value||0),method=(document.getElementById('payMethod') as HTMLSelectElement).value,ref=(document.getElementById('payRef') as HTMLInputElement).value.trim();if(amount<=0||amount>f.dueAmount)return alert('Payment must be greater than 0 and cannot exceed the current due.');const {data,error}=await supabase.rpc('create_payment_and_receipt',{p_amount:amount,p_fee_id:f.id,p_method:method,p_transaction_reference:ref||null});if(error)return alert(`Payment save failed: ${error.message}`);await feesPage()}}
function feeHistory(feeId:string){const f=feesCache.find(x=>x.id===feeId);if(!f)return;const rows=paymentsCache.filter(p=>p.feeId===feeId).map(p=>`<div class="history"><b>৳ ${p.amount.toLocaleString()}</b><span>${esc(p.method)}</span><small>${p.paidAt?new Date(p.paidAt).toLocaleString():'—'}${p.receipt?' • Receipt '+esc(p.receipt):''}${p.reference?' • Ref '+esc(p.reference):''}</small><button class="outline-btn" data-print-receipt="${esc(p.id)}">Print Receipt</button></div>`).join('');app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Payment History</h1><p>${esc(f.studentName)} • ${esc(f.feeType)}</p></div></div><div class="content-card"><div class="fee-overview"><div><span>Payable</span><b>৳ ${Math.max(0,f.amount-f.discount).toLocaleString()}</b></div><div><span>Paid</span><b>৳ ${f.paid.toLocaleString()}</b></div><div><span>Due</span><b>৳ ${f.dueAmount.toLocaleString()}</b></div></div>${rows||'<div class="empty-state"><h3>No payments yet</h3></div>'}</div></main>`;bind();document.querySelectorAll('[data-print-receipt]').forEach(b=>b.addEventListener('click',()=>printReceipt((b as HTMLElement).dataset.printReceipt!)))}
async function printReceipt(paymentId:string){const c=await context();if(!c)return;const p=paymentsCache.find(x=>x.id===paymentId);if(!p)return;const f=feesCache.find(x=>x.id===p.feeId);if(!f)return;const ir=await supabase.from('institutes').select('name,phone,email,address,logo_url').eq('id',c.instituteId).maybeSingle();const i=ir.data||{};const w=window.open('','_blank','width=760,height=900');if(!w)return;w.document.write(`<!doctype html><html><head><title>Receipt ${esc(p.receipt||p.id)}</title><style>body{font-family:Arial,sans-serif;padding:40px;max-width:700px;margin:auto;color:#111}.receipt{border:1px solid #ddd;border-radius:16px;padding:28px}h1{margin:0 0 4px}.muted{color:#666}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee}.total{font-size:22px;font-weight:700}@media print{button{display:none}}</style></head><body><div class="receipt"><h1>${esc(i.name||'Easylearn Institute')}</h1><div class="muted">${esc(i.phone||'')} ${i.email?'· '+esc(i.email):''}</div><div class="muted">${esc(i.address||'')}</div><hr><h2>Payment Receipt</h2><div class="row"><span>Receipt No.</span><b>${esc(p.receipt||'—')}</b></div><div class="row"><span>Student</span><b>${esc(f.studentName)}</b></div><div class="row"><span>Student ID</span><span>${esc(f.studentCode)}</span></div><div class="row"><span>Fee</span><span>${esc(f.feeType)}</span></div><div class="row"><span>Payment Date</span><span>${p.paidAt?new Date(p.paidAt).toLocaleString():'—'}</span></div><div class="row"><span>Method</span><span>${esc(p.method)}</span></div><div class="row"><span>Transaction Ref.</span><span>${esc(p.reference||'—')}</span></div><div class="row total"><span>Paid Amount</span><span>৳ ${p.amount.toLocaleString()}</span></div><p class="muted">Thank you for your payment.</p><button onclick="window.print()">Print</button></div></body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),300)}


type AttendanceRow={id:string;studentId:string;studentCode:string;studentName:string;status:string;note:string}
let attendanceBatches:any[]=[]
let attendanceRows:AttendanceRow[]=[]

async function loadAttendanceBatches(){
  const c=await context(); if(!c)return []
  const [br,cr]=await Promise.all([
    supabase.from('batches').select('id,name,course_id,status').eq('institute_id',c.instituteId).eq('status','active').order('name'),
    supabase.from('courses').select('id,name').eq('institute_id',c.instituteId).order('name')
  ])
  if(br.error){alert(`Batch load failed: ${br.error.message}`);return []}
  const cm=new Map((cr.data||[]).map((x:any)=>[x.id,x.name]))
  attendanceBatches=(br.data||[]).map((x:any)=>({...x,courseName:cm.get(x.course_id)||''}))
  return attendanceBatches
}

async function attendancePage(){
  await loadAttendanceBatches()
  const batchOpts=attendanceBatches.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}${b.courseName?' — '+esc(b.courseName):''}</option>`).join('')
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Attendance</h1><p>Take daily attendance by batch and review attendance history.</p></div></div><div class="content-card"><div class="form-grid"><div class="form-group"><label>Batch *</label><select id="attendanceBatch"><option value="">Select batch</option>${batchOpts}</select></div>${field('attendanceDate','Date','','date',today())}</div><div id="attendancePanel" class="empty-state"><div class="big-icon">✅</div><h3>Select a batch and date</h3><p>Students assigned to that batch will appear here.</p></div></div></main>`
  bind()
  const reload=()=>loadAttendanceSheet()
  document.getElementById('attendanceBatch')!.addEventListener('change',reload)
  document.getElementById('attendanceDate')!.addEventListener('change',reload)
}

async function loadAttendanceSheet(){
  const c=await context(); if(!c)return
  const batchId=(document.getElementById('attendanceBatch') as HTMLSelectElement)?.value
  const date=(document.getElementById('attendanceDate') as HTMLInputElement)?.value
  const panel=document.getElementById('attendancePanel'); if(!panel)return
  if(!batchId||!date){panel.innerHTML='<div class="empty-state"><div class="big-icon">✅</div><h3>Select a batch and date</h3><p>Students assigned to that batch will appear here.</p></div>';return}
  panel.innerHTML='<div class="empty-state"><p>Loading students...</p></div>'
  const [sr,ar]=await Promise.all([
    supabase.from('batch_students').select('student_id,students!inner(id,student_id,full_name,status)').eq('institute_id',c.instituteId).eq('batch_id',batchId),
    supabase.from('attendance').select('id,student_id,status,notes').eq('institute_id',c.instituteId).eq('batch_id',batchId).eq('attendance_date',date)
  ])
  if(sr.error){panel.innerHTML=`<div class="empty-state"><h3>Could not load students</h3><p>${esc(sr.error.message)}</p></div>`;return}
  if(ar.error){panel.innerHTML=`<div class="empty-state"><h3>Could not load attendance</h3><p>${esc(ar.error.message)}</p></div>`;return}
  const existing=new Map<string, any>((ar.data||[]).map((x:any)=>[String(x.student_id),x]))
  attendanceRows=(sr.data||[]).map((x:any)=>{const st=x.students;const old=existing.get(st.id);return{id:old?.id||'',studentId:st.id,studentCode:st.student_id||'',studentName:st.full_name||'',status:old?.status||'present',note:old?.notes||''}})
  if(!attendanceRows.length){panel.innerHTML='<div class="empty-state"><div class="big-icon">👨‍🎓</div><h3>No students assigned</h3><p>Assign students to this batch first.</p></div>';return}
  panel.innerHTML=`<div class="attendance-toolbar"><div><b>${attendanceRows.length} students</b><span>Choose Present, Absent, Late or Leave</span></div><div class="attendance-actions"><button class="outline-btn" id="markAllPresent">Mark all Present</button><button class="primary-btn" id="saveAttendance">Save Attendance</button></div></div><div class="attendance-table">${attendanceRows.map((r,i)=>`<div class="attendance-row"><div class="student-info"><b>${esc(r.studentName)}</b><small>${esc(r.studentCode)}</small></div><select data-att-status="${i}"><option value="present" ${r.status==='present'?'selected':''}>Present</option><option value="absent" ${r.status==='absent'?'selected':''}>Absent</option><option value="late" ${r.status==='late'?'selected':''}>Late</option><option value="leave" ${r.status==='leave'?'selected':''}>Leave</option></select><input data-att-note="${i}" placeholder="Note (optional)" value="${esc(r.note)}"/></div>`).join('')}</div><div class="attendance-summary" id="attendanceSummary"></div>`
  const updateSummary=()=>{attendanceRows.forEach((r,i)=>{r.status=(document.querySelector(`[data-att-status="${i}"]`) as HTMLSelectElement).value;r.note=(document.querySelector(`[data-att-note="${i}"]`) as HTMLInputElement).value.trim()});const counts={present:0,absent:0,late:0,leave:0};attendanceRows.forEach(r=>counts[r.status as keyof typeof counts]++);document.getElementById('attendanceSummary')!.innerHTML=`<div><span>Present</span><b>${counts.present}</b></div><div><span>Absent</span><b>${counts.absent}</b></div><div><span>Late</span><b>${counts.late}</b></div><div><span>Leave</span><b>${counts.leave}</b></div>`}
  document.querySelectorAll('[data-att-status],[data-att-note]').forEach(x=>x.addEventListener('change',updateSummary));document.querySelectorAll('[data-att-note]').forEach(x=>x.addEventListener('input',updateSummary));updateSummary()
  document.getElementById('markAllPresent')!.addEventListener('click',()=>{document.querySelectorAll<HTMLSelectElement>('[data-att-status]').forEach(x=>x.value='present');updateSummary()})
  document.getElementById('saveAttendance')!.addEventListener('click',async()=>{updateSummary();const user=c.user;const payload=attendanceRows.map(r=>({institute_id:c.instituteId,student_id:r.studentId,batch_id:batchId,attendance_date:date,status:r.status,notes:r.note||null}));const {error}=await supabase.from('attendance').upsert(payload,{onConflict:'institute_id,batch_id,student_id,date'});if(error)return alert(`Attendance save failed: ${error.message}`);alert('Attendance saved successfully.');await loadAttendanceSheet()})
}



type Routine={id:string;batchId:string;batchName:string;teacherId:string;teacherName:string;day:string;startTime:string;endTime:string;topic:string;room:string}
let routineCache:Routine[]=[]

const routineDays=['Saturday','Sunday','Monday','Tuesday','Wednesday','Thursday','Friday']
async function loadRoutine(){
  const c=await context();if(!c)return []
  const [rr,br,tr]=await Promise.all([
    supabase.from('routines').select('id,batch_id,teacher_id,day_of_week,start_time,end_time,topic,room').eq('institute_id',c.instituteId).order('day_of_week').order('start_time'),
    supabase.from('batches').select('id,name').eq('institute_id',c.instituteId).order('name'),
    supabase.from('teachers').select('id,name').eq('institute_id',c.instituteId).order('name')
  ])
  if(rr.error){alert(`Routine load failed: ${rr.error.message}`);return []}
  const bm=new Map((br.data||[]).map((x:any)=>[x.id,x.name]));const tm=new Map((tr.data||[]).map((x:any)=>[x.id,x.name]))
  routineCache=(rr.data||[]).map((r:any)=>({id:r.id,batchId:r.batch_id||'',batchName:bm.get(r.batch_id)||'Unknown batch',teacherId:r.teacher_id||'',teacherName:tm.get(r.teacher_id)||'Unassigned',day:r.day_of_week||'',startTime:String(r.start_time||'').slice(0,5),endTime:String(r.end_time||'').slice(0,5),topic:r.topic||'',room:r.room||''}))
  return routineCache
}
function routineCard(r:Routine){return `<div class="student-card"><div class="student-avatar">${esc((r.day||'?').slice(0,2).toUpperCase())}</div><div class="student-info"><b>${esc(r.day)} • ${esc(r.startTime)}${r.endTime?' – '+esc(r.endTime):''}</b><small>Batch: ${esc(r.batchName)}</small><small>Teacher: ${esc(r.teacherName)}${r.room?' • Room '+esc(r.room):''}</small>${r.topic?`<small>Topic: ${esc(r.topic)}</small>`:''}</div><div style="display:flex;gap:8px"><button class="outline-btn" data-routine-edit="${esc(r.id)}">Edit</button><button class="danger-btn" data-routine-delete="${esc(r.id)}">Delete</button></div></div>`}
function routineWeeklyGrid(rows:Routine[]){return `<div class="routine-week-grid">${routineDays.map(day=>{const dayRows=rows.filter(r=>r.day===day);return `<div class="routine-day"><div class="routine-day-title">${esc(day)}</div>${dayRows.length?dayRows.map(r=>`<div class="routine-slot"><b>${esc(r.startTime)}–${esc(r.endTime)}</b><span>${esc(r.batchName)}</span><small>${esc(r.teacherName)}${r.room?' · '+esc(r.room):''}</small>${r.topic?`<small>${esc(r.topic)}</small>`:''}</div>`).join(''):'<div class="routine-empty">No class</div>'}</div>`}).join('')}</div>`}
async function routinePage(editId:string|null=null){await loadRoutine();const c=await context();if(!c)return
  const [bRes,tRes]=await Promise.all([supabase.from('batches').select('id,name,status').eq('institute_id',c.instituteId).eq('status','active').order('name'),supabase.from('teachers').select('id,name,status').eq('institute_id',c.instituteId).eq('status','active').order('name')])
  const batches=bRes.data||[],teachers=tRes.data||[];const editing=editId?routineCache.find(r=>r.id===editId):null
  const bo=batches.map((x:any)=>`<option value="${esc(x.id)}" ${editing?.batchId===x.id?'selected':''}>${esc(x.name)}</option>`).join('');const to=teachers.map((x:any)=>`<option value="${esc(x.id)}" ${editing?.teacherId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')
  const dayOptions=routineDays.map(d=>`<option value="${esc(d)}" ${editing?.day===d?'selected':''}>${esc(d)}</option>`).join('')
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Routine / Class Schedule</h1><p>Build and manage the weekly class timetable.</p></div></div><div class="content-card"><div class="form-grid"><div class="form-group"><label>Batch *</label><select id="routineBatch"><option value="">Select batch</option>${bo}</select></div><div class="form-group"><label>Teacher</label><select id="routineTeacher"><option value="">Unassigned</option>${to}</select></div><div class="form-group"><label>Day *</label><select id="routineDay"><option value="">Select day</option>${dayOptions}</select></div>${field('routineStart','Start time','','time')}${field('routineEnd','End time','','time')}${field('routineTopic','Subject / Topic','e.g. Grammar')}${field('routineRoom','Room','e.g. Room 201')}</div><div class="form-actions"><button class="outline-btn" id="cancelRoutine" ${editing?'':'style="display:none"'}>Cancel</button><button class="primary-btn" id="saveRoutine">${editing?'Update Schedule':'Add to Routine'}</button></div></div><div class="content-card"><div class="toolbar"><input id="routineSearch" class="search-input" placeholder="Search batch, teacher, topic or room..."/><select id="routineDayFilter"><option value="">All days</option>${routineDays.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('')}</select><select id="routineBatchFilter"><option value="">All batches</option>${bo}</select></div><div class="student-list-header"><b id="routineCount">${routineCache.length} schedule entries</b><span>Weekly routine</span></div><div id="routineGrid">${routineWeeklyGrid(routineCache)}</div><div class="students-list" id="routineList" style="margin-top:18px"></div></div></main>`;bind()
  if(editing){(document.getElementById('routineStart') as HTMLInputElement).value=editing.startTime;(document.getElementById('routineEnd') as HTMLInputElement).value=editing.endTime;(document.getElementById('routineTopic') as HTMLInputElement).value=editing.topic;(document.getElementById('routineRoom') as HTMLInputElement).value=editing.room}
  const filtered=()=>{const q=((document.getElementById('routineSearch') as HTMLInputElement)?.value||'').toLowerCase();const day=(document.getElementById('routineDayFilter') as HTMLSelectElement)?.value||'';const batch=(document.getElementById('routineBatchFilter') as HTMLSelectElement)?.value||'';return routineCache.filter(r=>(!q||[r.batchName,r.teacherName,r.topic,r.room,r.day].join(' ').toLowerCase().includes(q))&&(!day||r.day===day)&&(!batch||r.batchId===batch))}
  const render=()=>{const rows=filtered();document.getElementById('routineCount')!.textContent=`${rows.length} schedule entries`;document.getElementById('routineGrid')!.innerHTML=routineWeeklyGrid(rows);document.getElementById('routineList')!.innerHTML=rows.length?rows.map(routineCard).join(''):'<div class="empty-state"><h3>No matching classes</h3><p>Try another filter or add a schedule.</p></div>';bindRoutineActions()}
  const bindRoutineActions=()=>{document.querySelectorAll('[data-routine-edit]').forEach(b=>b.addEventListener('click',()=>routinePage((b as HTMLElement).dataset.routineEdit||null)));document.querySelectorAll('[data-routine-delete]').forEach(b=>b.addEventListener('click',async()=>{const id=(b as HTMLElement).dataset.routineDelete!;if(!confirm('Delete this routine entry?'))return;const {error}=await supabase.from('routines').delete().eq('id',id);if(error)return alert(`Delete failed: ${error.message}`);await routinePage()}))}
  ;['routineSearch','routineDayFilter','routineBatchFilter'].forEach(id=>document.getElementById(id)?.addEventListener('input',render));render()
  document.getElementById('cancelRoutine')?.addEventListener('click',()=>routinePage())
  document.getElementById('saveRoutine')!.onclick=async()=>{const v=(id:string)=>(document.getElementById(id) as HTMLInputElement).value.trim();const batchId=(document.getElementById('routineBatch') as HTMLSelectElement).value;const teacherId=(document.getElementById('routineTeacher') as HTMLSelectElement).value||null;const day=(document.getElementById('routineDay') as HTMLSelectElement).value;const start=v('routineStart'),end=v('routineEnd');if(!batchId||!day||!start||!end)return alert('Batch, day, start time and end time are required.');if(end<=start)return alert('End time must be after start time.');
    const conflict=routineCache.find(r=>r.id!==(editing?.id||'')&&r.day===day&&((teacherId&&r.teacherId===teacherId)||(r.batchId===batchId)||(v('routineRoom')&&r.room===v('routineRoom')))&&r.startTime<end&&start<r.endTime)
    if(conflict)return alert(`Schedule conflict: ${conflict.day} ${conflict.startTime}-${conflict.endTime} (${conflict.batchName}${conflict.room?' · '+conflict.room:''}).`)
    const payload={institute_id:c.instituteId,batch_id:batchId,teacher_id:teacherId,day_of_week:day,start_time:start,end_time:end,topic:v('routineTopic')||null,room:v('routineRoom')||null}
    const res=editing?await supabase.from('routines').update(payload).eq('id',editing.id).eq('institute_id',c.instituteId):await supabase.from('routines').insert(payload)
    if(res.error)return alert(`${editing?'Routine update':'Routine save'} failed: ${res.error.message}`);await routinePage()}
}

async function attendanceMonthlyReportPage(){const c=await context();if(!c)return
  const [br,sr]=await Promise.all([supabase.from('batches').select('id,name').eq('institute_id',c.instituteId).order('name'),supabase.from('students').select('id,student_id,full_name,status').eq('institute_id',c.instituteId).eq('status','active').order('full_name')])
  if(br.error)return alert(`Batch load failed: ${br.error.message}`)
  if(sr.error)return alert(`Student load failed: ${sr.error.message}`)
  const studentMap=new Map<string, any>((sr.data||[]).map((x:any)=>[String(x.id),x])); const defaultMonth=new Date().toISOString().slice(0,7)
  const render=async()=>{const month=(document.getElementById('attReportMonth') as HTMLInputElement)?.value||defaultMonth;const batchId=(document.getElementById('attReportBatch') as HTMLSelectElement)?.value||'';const [yy,mm]=month.split('-').map(Number);const next=new Date(Date.UTC(yy,mm,1)).toISOString().slice(0,10);const {data,error}=await supabase.from('attendance').select('student_id,batch_id,attendance_date,status').eq('institute_id',c.instituteId).gte('attendance_date',`${month}-01`).lt('attendance_date',next).order('attendance_date');const box=document.getElementById('attReportBody');if(!box)return;if(error){box.innerHTML=`<div class="empty-state"><h3>Could not load report</h3><p>${esc(error.message)}</p></div>`;return}const rows=(data||[]).filter((r:any)=>!batchId||r.batch_id===batchId);const totals:any={present:0,absent:0,late:0,leave:0};rows.forEach((r:any)=>{if(r.status in totals)totals[r.status]++});const days=new Set(rows.map((r:any)=>r.attendance_date)).size;const byStudent=new Map<string,any>();rows.forEach((r:any)=>{const st=studentMap.get(r.student_id);if(!st)return;const x=byStudent.get(r.student_id)||{name:st.full_name,id:st.student_id,present:0,absent:0,late:0,leave:0,total:0};if(r.status in totals)x[r.status]++;x.total++;byStudent.set(r.student_id,x)});const report=[...byStudent.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name)));const rate=rows.length?Math.round((totals.present+totals.late)/rows.length*100):0;box.innerHTML=`<div class="attendance-summary"><div><span>Records</span><b>${rows.length}</b></div><div><span>Class Days</span><b>${days}</b></div><div><span>Present</span><b>${totals.present}</b></div><div><span>Absent</span><b>${totals.absent}</b></div><div><span>Late</span><b>${totals.late}</b></div><div><span>Rate</span><b>${rate}%</b></div></div>${report.length?`<div class="attendance-report-table"><div class="attendance-report-head"><b>Student</b><b>Present</b><b>Absent</b><b>Late</b><b>Leave</b><b>Rate</b></div>${report.map(r=>{const rr=r.total?Math.round((r.present+r.late)/r.total*100):0;return `<div class="attendance-report-row"><span><b>${esc(r.name)}</b><small>${esc(r.id||'—')}</small></span><span>${r.present}</span><span>${r.absent}</span><span>${r.late}</span><span>${r.leave}</span><span><b>${rr}%</b></span></div>`}).join('')}</div>`:'<div class="empty-state"><h3>No attendance records</h3><p>No attendance found for the selected month/batch.</p></div>'}`}
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Monthly Attendance Report</h1><p>Student-wise attendance summary.</p></div><div class="form-actions"><button class="outline-btn" data-page="attendance-history">History</button><button class="primary-btn" id="printAttReport">Print Report</button></div></div><div class="content-card"><div class="toolbar"><input id="attReportMonth" class="month-input" type="month" value="${defaultMonth}"/><select id="attReportBatch"><option value="">All batches</option>${(br.data||[]).map((x:any)=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div><div id="attReportBody"><div class="empty-state"><p>Loading report...</p></div></div></div></main>`;bind();document.getElementById('attReportMonth')!.addEventListener('change',render);document.getElementById('attReportBatch')!.addEventListener('change',render);document.getElementById('printAttReport')!.addEventListener('click',()=>window.print());await render()
}

async function attendanceHistoryPage(){const c=await context();if(!c)return
  const batchIdParam='';
  const [ar,br]=await Promise.all([supabase.from('attendance').select('id,batch_id,student_id,attendance_date,status,notes').eq('institute_id',c.instituteId).order('attendance_date',{ascending:false}).limit(500),supabase.from('batches').select('id,name').eq('institute_id',c.instituteId).order('name')])
  if(ar.error)return alert(`Attendance history failed: ${ar.error.message}`)
  const batchMap=new Map((br.data||[]).map((x:any)=>[x.id,x.name]));const rows=(ar.data||[])
  const studentIds=[...new Set(rows.map((x:any)=>x.student_id))];let students:any[]=[];if(studentIds.length){const sr=await supabase.from('students').select('id,student_id,full_name').in('id',studentIds);if(sr.error)return alert(`Student load failed: ${sr.error.message}`);students=sr.data||[]}
  const sm=new Map(students.map(x=>[x.id,x]));
  const render=()=>{const q=((document.getElementById('attHistorySearch') as HTMLInputElement)?.value||'').toLowerCase();const b=(document.getElementById('attHistoryBatch') as HTMLSelectElement)?.value||'';const m=(document.getElementById('attHistoryMonth') as HTMLInputElement)?.value||'';const list=rows.filter((r:any)=>(!b||r.batch_id===b)&&(!m||String(r.attendance_date).startsWith(m))).filter((r:any)=>{const st=sm.get(r.student_id);return !q||[st?.full_name,st?.student_id,batchMap.get(r.batch_id),r.status].join(' ').toLowerCase().includes(q)});const box=document.getElementById('attHistoryList');if(box)box.innerHTML=list.length?list.map((r:any)=>{const st=sm.get(r.student_id);return `<div class="student-card"><div class="student-avatar">${initials(st?.full_name||'ST')}</div><div class="student-info"><b>${esc(st?.full_name||'Unknown')}</b><small>${esc(st?.student_id||'')} • ${esc(batchMap.get(r.batch_id)||'Unknown batch')}</small><small>${esc(r.attendance_date)} • ${esc(r.status)}${r.notes?' • '+esc(r.notes):''}</small></div></div>`}).join(''):`<div class="empty-state"><h3>No attendance records</h3><p>Try another filter.</p></div>`;const s=document.getElementById('attHistorySummary');if(s){const cts={present:0,absent:0,late:0,leave:0};list.forEach((r:any)=>cts[r.status as keyof typeof cts]++);s.innerHTML=`<div><span>Present</span><b>${cts.present}</b></div><div><span>Absent</span><b>${cts.absent}</b></div><div><span>Late</span><b>${cts.late}</b></div><div><span>Leave</span><b>${cts.leave}</b></div>`}}
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Attendance History</h1><p>Review daily and monthly attendance records.</p></div><div class="form-actions"><button class="outline-btn" data-page="attendance-monthly-report">Monthly Report</button><button class="primary-btn" data-page="attendance">Take Attendance</button></div></div><div class="content-card"><div class="toolbar"><input id="attHistorySearch" class="search-input" placeholder="Search student, ID, batch..."/><select id="attHistoryBatch"><option value="">All batches</option>${(br.data||[]).map((x:any)=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select>${field('attHistoryMonth','Month','','month')}</div><div class="attendance-summary" id="attHistorySummary"></div><div id="attHistoryList" class="students-list"></div></div></main>`;bind();['attHistorySearch','attHistoryBatch','attHistoryMonth'].forEach(id=>document.getElementById(id)?.addEventListener('input',render));render()
}


type Staff={id:string;name:string;phone:string;email:string;designation:string;joiningDate:string;salary:number;status:string;photoUrl:string;photoPath:string}
let staffCache:Staff[]=[]
let salaryCache:any[]=[]

async function loadStaff(){
  const c=await context(); if(!c)return []
  const {data,error}=await supabase.from('teachers').select('id,name,phone,email,designation,joining_date,salary,status,photo_url').eq('institute_id',c.instituteId).order('created_at',{ascending:false})
  if(error){alert(`Staff load failed: ${error.message}`);return []}
  staffCache=await Promise.all((data||[]).map(async(r:any)=>({id:r.id,name:r.name||r.full_name||'',phone:r.phone||'',email:r.email||'',designation:r.designation||'Teacher',joiningDate:r.joining_date||'',salary:Number(r.salary||0),status:r.status||'active',photoUrl:await privatePhotoUrl('teacher-photos',r.photo_url||''),photoPath:r.photo_url||''})));return staffCache
}
function staffCard(s:Staff){return `<div class="student-card"><div class="student-avatar">${s.photoUrl?`<img src="${esc(s.photoUrl)}" alt="${esc(s.name)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%"/>`:initials(s.name)}</div><div class="student-info"><b>${esc(s.name)}</b><small>${esc(s.designation)}</small><small>📞 ${esc(s.phone||'No phone')}</small><small>Salary: ৳ ${s.salary.toLocaleString()}</small></div><span class="status ${s.status==='active'?'active':'inactive'}">${esc(s.status)}</span><button class="outline-btn" data-staff-edit="${esc(s.id)}">Edit</button><button class="danger-btn" data-staff-toggle="${esc(s.id)}">${s.status==='active'?'Deactivate':'Activate'}</button></div>`}
async function staffPage(){
  await loadStaff();
  app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Teachers / Staff</h1><p>Manage teacher profiles, roles, salary and active status.</p></div><button class="primary-btn" data-staff-add>+ Add Staff</button></div><div class="content-card"><div class="toolbar"><input id="staffSearch" class="search-input" placeholder="Search name, phone, email or designation..."/><select id="staffStatus"><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div id="staffCount" class="student-list-header"></div><div id="staffList" class="students-list"></div></div><div class="content-card"><div class="page-header"><div><h2>Salary Management</h2><p>Monthly payroll, paid amount, due amount and payment history.</p></div><button class="primary-btn" data-salary-add>+ Record Salary</button></div><div class="toolbar"><input id="salarySearch" class="search-input" placeholder="Search staff..."/><input id="salaryFilterMonth" class="search-input" type="month"/></div><div id="salarySummary"></div><div id="salaryList" class="students-list"></div></div></main>`;bind()
  document.querySelector('[data-staff-add]')?.addEventListener('click',()=>staffForm())
  document.querySelector('[data-salary-add]')?.addEventListener('click',()=>salaryForm());document.getElementById('salarySearch')?.addEventListener('input',renderSalaries);document.getElementById('salaryFilterMonth')?.addEventListener('change',renderSalaries);document.querySelectorAll('[data-salary-delete]').forEach(b=>b.addEventListener('click',async()=>{const id=(b as HTMLElement).dataset.salaryDelete;if(!id||!confirm('Delete this salary record?'))return;const {error}=await supabase.from('salaries').delete().eq('id',id);if(error)return alert(`Salary delete failed: ${error.message}`);await staffPage()}));document.querySelectorAll('[data-salary-edit]').forEach(b=>b.addEventListener('click',()=>{const id=(b as HTMLElement).dataset.salaryEdit;const r=salaryCache.find(x=>x.id===id);if(r)salaryForm(r)}))
  renderStaff();document.getElementById('staffSearch')?.addEventListener('input',renderStaff);document.getElementById('staffStatus')?.addEventListener('change',renderStaff)
  await loadSalaries();renderSalaries()
}
function renderStaff(){const q=((document.getElementById('staffSearch') as HTMLInputElement)?.value||'').toLowerCase(),f=(document.getElementById('staffStatus') as HTMLSelectElement)?.value||'all';const list=staffCache.filter(s=>(f==='all'||s.status===f)&&[s.name,s.phone,s.email,s.designation].join(' ').toLowerCase().includes(q));const c=document.getElementById('staffCount');if(c)c.innerHTML=`<b>${list.length} Staff</b><span>${staffCache.filter(x=>x.status==='active').length} active</span>`;const box=document.getElementById('staffList');if(box)box.innerHTML=list.length?list.map(staffCard).join(''):`<div class="empty-state"><div class="big-icon">👨‍🏫</div><h3>No staff found</h3><p>Add your first teacher or staff member.</p></div>`;document.querySelectorAll('[data-staff-edit]').forEach(b=>b.addEventListener('click',()=>staffForm(staffCache.find(x=>x.id===(b as HTMLElement).dataset.staffEdit))));document.querySelectorAll('[data-staff-toggle]').forEach(b=>b.addEventListener('click',()=>toggleStaff((b as HTMLElement).dataset.staffToggle!)))}
