 app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Exams & Results</h1><p>Create exams, subjects and record student marks.</p></div><button class="primary-btn" id="addExam">+ Add Exam</button></div><div class="content-card"><div id="examList" class="students-list">${examCache.length?examCache.map(e=>`<div class="student-card"><div class="student-avatar">EX</div><div class="student-info"><b>${esc(e.name)}</b><small>${esc(e.batchName)} • ${esc(e.examDate)}</small></div><button class="outline-btn" data-result-exam="${esc(e.id)}">Results</button></div>`).join(''):'<div class="empty-state"><div class="big-icon">📝</div><h3>No exams yet</h3><p>Create your first exam.</p></div>'}</div></div></main>`;bind();document.getElementById('addExam')!.onclick=()=>examForm();document.querySelectorAll('[data-result-exam]').forEach(b=>b.addEventListener('click',()=>resultPage((b as HTMLElement).dataset.resultExam!)))
