async function subjectForm(examId:string){const c=await context();if(!c)return;app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Add Exam Subject</h1><p>Add subjects and total marks, then enter results.</p></div></div><div class="content-card"><div class="form-grid">${field('subjectName','Subject name *','e.g. English')}${field('totalMarks','Total marks *','100','number')}</div><div class="form-actions"><button class="outline-btn" data-page="exams">Later</button><button class="primary-btn" id="saveSubject">Add Subject</button></div></div></main>`;bind();document.getElementById('saveSubject')!.onclick=async()=>{const n=(document.getElementById('subjectName') as HTMLInputElement).value.trim(),m=Number((document.getElementById('totalMarks') as HTMLInputElement).value||0);if(!n||m<=0)return alert('Subject and total marks are required.');const {error}=await supabase.from('exam_subjects').insert({institute_id:c.instituteId,exam_id:examId,subject_name:n,total_marks:m});if(error)return alert(`Subject save failed: ${error.message}`);await examsPage()}}
function gradeFromPercent(p:number){if(p>=80)return 'A+';if(p>=70)return 'A';if(p>=60)return 'A-';if(p>=50)return 'B';if(p>=40)return 'C';if(p>=33)return 'D';return 'F'}

async function resultPage(examId:string){const c=await context();if(!c)return;const exam=examCache.find(x=>x.id===examId);if(!exam){await examsPage();return}const [asr,subr]=await Promise.all([supabase.from('batch_students').select('student_id').eq('institute_id',c.instituteId).eq('batch_id',exam.batchId),supabase.from('exam_subjects').select('id,subject_name,total_marks').eq('institute_id',c.instituteId).eq('exam_id',examId).order('subject_name')]);if(asr.error||subr.error)return alert(`Result load failed: ${(asr.error||subr.error)?.message}`);const studentIds=(asr.data||[]).map((x:any)=>x.student_id).filter(Boolean);const sr=studentIds.length?await supabase.from('students').select('id,student_id,full_name').eq('institute_id',c.instituteId).eq('status','active').in('id',studentIds).order('full_name'):({data:[],error:null} as any);if(sr.error)return alert(`Student load failed: ${sr.error.message}`);const students=sr.data||[],subs=subr.data||[];if(!subs.length){return app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${esc(exam.name)} — Results</h1></div><button class="outline-btn" data-page="exams">Back</button></div><div class="content-card empty-state"><h3>No subjects yet</h3><p>Add a subject before entering marks.</p><button class="primary-btn" id="addSubjectNow">+ Add Subject</button></div></main>`,bind(),void(document.getElementById('addSubjectNow')!.addEventListener('click',()=>subjectForm(examId)))}
 const opts=students.map((st:any)=>`<option value="${esc(st.id)}">${esc(st.full_name)}${st.student_id?' — '+esc(st.student_id):''}</option>`).join('');const so=subs.map((x:any)=>`<option value="${esc(x.id)}">${esc(x.subject_name)} (out of ${x.total_marks})</option>`).join('');app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${esc(exam.name)} — Results</h1><p>${esc(exam.batchName)} • ${esc(exam.examDate)}</p></div><button class="outline-btn" data-page="exams">Back</button></div><div class="content-card"><div class="form-grid"><div class="form-group"><label>Student *</label><select id="resultStudent"><option value="">Select student</option>${opts}</select></div><div class="form-group"><label>Subject *</label><select id="resultSubject">${so}</select></div>${field('resultMarks','Marks *','0','number')}${field('resultGrade','Grade','Auto if blank')}${field('resultRemarks','Remarks','Optional')}</div><div class="form-actions"><button class="primary-btn" id="saveResult">Save Result</button></div><div class="notice-box"><b>Grade scale</b><p>A+ 80–100 · A 70–79 · A− 60–69 · B 50–59 · C 40–49 · D 33–39 · F below 33</p></div></div><div class="content-card"><h2>Result Summary</h2><div id="resultSummary">Loading...</div></div><div class="content-card"><h2>Recent results</h2><div id="resultList">Loading...</div></div></main>`;bind();await renderResults(examId,students,subs);document.getElementById('resultMarks')!.addEventListener('input',()=>{const subject=(document.getElementById('resultSubject') as HTMLSelectElement).value,total=Number((subs.find((x:any)=>x.id===subject) as any)?.total_marks||0),marks=Number((document.getElementById('resultMarks') as HTMLInputElement).value||0),g=document.getElementById('resultGrade') as HTMLInputElement;if(total>0&&marks>=0&&marks<=total)g.value=gradeFromPercent((marks/total)*100)});document.getElementById('saveResult')!.onclick=async()=>{const student=(document.getElementById('resultStudent') as HTMLSelectElement).value,subject=(document.getElementById('resultSubject') as HTMLSelectElement).value,marks=Number((document.getElementById('resultMarks') as HTMLInputElement).value||0),grade=(document.getElementById('resultGrade') as HTMLInputElement).value.trim(),remarks=(document.getElementById('resultRemarks') as HTMLInputElement).value.trim(),total=Number((subs.find((x:any)=>x.id===subject) as any)?.total_marks||0);if(!student||!subject||marks<0||marks>total)return alert(`Marks must be between 0 and ${total}.`);const {error}=await supabase.from('results').upsert({institute_id:c.instituteId,exam_id:examId,exam_subject_id:subject,student_id:student,marks,grade:grade||gradeFromPercent((marks/total)*100),remarks:remarks||null},{onConflict:'institute_id,exam_subject_id,student_id'});if(error)return alert(`Result save failed: ${error.message}`);(document.getElementById('resultMarks') as HTMLInputElement).value='';(document.getElementById('resultGrade') as HTMLInputElement).value='';(document.getElementById('resultRemarks') as HTMLInputElement).value='';await renderResults(examId,students,subs)}}
async function renderResults(examId:string,students:any[],subs:any[]){const c=await context();if(!c)return;const {data,error}=await supabase.from('results').select('id,student_id,exam_subject_id,marks,grade,remarks').eq('institute_id',c.instituteId).eq('exam_id',examId).order('created_at',{ascending:false}).limit(500);if(error)return;const rows:any[]=data||[],sm=new Map(students.map(x=>[x.id,x.full_name])),mm=new Map(subs.map(x=>[x.id,x.subject_name]));const box=document.getElementById('resultList');if(box)box.innerHTML=rows.length?rows.map((r:any)=>`<div class="history"><b>${esc(sm.get(r.student_id)||'Unknown')}</b><span>${esc(mm.get(r.exam_subject_id)||'Unknown')} • ${Number(r.marks).toFixed(2)}</span><small>Grade ${esc(r.grade||'—')}${r.remarks?` • ${esc(r.remarks)}`:''}</small></div>`).join(''):'<div class="empty-state"><p>No results recorded yet.</p></div>';const summary=document.getElementById('resultSummary');if(summary){const byStudent=new Map<string,any[]>();rows.forEach(r=>{const a=byStudent.get(r.student_id)||[];a.push(r);byStudent.set(r.student_id,a)});const cards=[...byStudent.entries()].map(([sid,rs])=>{const total=rs.reduce((a,r)=>a+Number(r.marks||0),0);const max=rs.reduce((a,r)=>{const sub=subs.find(x=>x.id===r.exam_subject_id);return a+Number(sub?.total_marks||0)},0);const pct=max?total/max*100:0;return `<div class="history"><b>${esc(sm.get(sid)||'Unknown')}</b><span>Total ${total.toFixed(2)} / ${max.toFixed(2)} • ${pct.toFixed(1)}%</span><small>Subjects recorded: ${rs.length}/${subs.length} • Grade ${gradeFromPercent(pct)}</small></div>`}).join('');summary.innerHTML=cards||'<div class="empty-state"><p>No student results yet.</p></div>'}}

type Enquiry={id:string;name:string;phone:string;courseName:string;batchName:string;source:string;followUp:string;status:string;notes:string}
let enquiryCache:Enquiry[]=[]
async function enquiriesPage(){const c=await context();if(!c)return;const [er,cr,br]=await Promise.all([supabase.from('enquiries').select('id,name,phone,course_id,batch_id,source,notes,follow_up_date,status').eq('institute_id',c.instituteId).order('created_at',{ascending:false}),supabase.from('courses').select('id,name').eq('institute_id',c.instituteId).order('name'),supabase.from('batches').select('id,name').eq('institute_id',c.instituteId).order('name')]);if(er.error)return alert(`Enquiry load failed: ${er.error.message}`);const cm=new Map((cr.data||[]).map((x:any)=>[x.id,x.name])),bm=new Map((br.data||[]).map((x:any)=>[x.id,x.name]));enquiryCache=(er.data||[]).map((x:any)=>({id:x.id,name:x.name,phone:x.phone||'',courseName:cm.get(x.course_id)||'',batchName:bm.get(x.batch_id)||'',source:x.source||'',followUp:x.follow_up_date||'',status:x.status,notes:x.notes||''}));app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Enquiries</h1><p>Track leads from first contact through admission.</p></div><button class="primary-btn" id="addEnquiry">+ Add Enquiry</button></div><div class="content-card"><div class="toolbar"><input id="enquirySearch" class="search-input" placeholder="Search name, phone, course..."/><select id="enquiryStatus"><option value="">All status</option>${['new','contacted','interested','admitted','not_interested','lost'].map(x=>`<option value="${x}">${x.replace('_',' ')}</option>`).join('')}</select></div><div id="enquiryList" class="students-list"></div></div></main>`;bind();document.getElementById('addEnquiry')!.onclick=()=>enquiryForm();const render=()=>{const q=((document.getElementById('enquirySearch') as HTMLInputElement).value||'').toLowerCase(),st=(document.getElementById('enquiryStatus') as HTMLSelectElement).value;const list=enquiryCache.filter(x=>(!st||x.status===st)&&[x.name,x.phone,x.courseName,x.batchName,x.source].join(' ').toLowerCase().includes(q));document.getElementById('enquiryList')!.innerHTML=list.length?list.map(x=>`<div class="student-card"><div class="student-avatar">EN</div><div class="student-info"><b>${esc(x.name)}</b><small>${esc(x.phone||'No phone')}${x.courseName?' • '+esc(x.courseName):''}${x.batchName?' • '+esc(x.batchName):''}</small><small>Status: ${esc(x.status)}${x.followUp?' • Follow-up '+esc(x.followUp):''}</small></div><button class="outline-btn" data-enquiry-edit="${esc(x.id)}">Edit</button></div>`).join(''):'<div class="empty-state"><h3>No enquiries</h3><p>Add a new enquiry to start lead tracking.</p></div>';document.querySelectorAll('[data-enquiry-edit]').forEach(b=>b.addEventListener('click',()=>enquiryForm(enquiryCache.find(x=>x.id===(b as HTMLElement).dataset.enquiryEdit))))};render();document.getElementById('enquirySearch')!.addEventListener('input',render);document.getElementById('enquiryStatus')!.addEventListener('change',render)}
async function enquiryForm(existing?:Enquiry){const c=await context();if(!c)return;const [cr,br]=await Promise.all([supabase.from('courses').select('id,name').eq('institute_id',c.instituteId).order('name'),supabase.from('batches').select('id,name').eq('institute_id',c.instituteId).order('name')]);const v=(x:string)=>existing?.[x as keyof Enquiry]||'';app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${existing?'Edit':'Add'} Enquiry</h1></div></div><div class="content-card"><div class="form-grid">${field('enqName','Name *','Name',undefined,String(v('name')))}${field('enqPhone','Phone','Phone',undefined,String(v('phone')))}<div class="form-group"><label>Course</label><select id="enqCourse"><option value="">Select course</option>${(cr.data||[]).map((x:any)=>`<option value="${esc(x.id)}" ${x.name===v('courseName')?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="form-group"><label>Batch</label><select id="enqBatch"><option value="">Select batch</option>${(br.data||[]).map((x:any)=>`<option value="${esc(x.id)}" ${x.name===v('batchName')?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${field('enqSource','Source','Facebook / Referral / Walk-in',undefined,String(v('source')))}${field('enqFollow','Follow-up date','','date',String(v('followUp')))}${select('enqStatus','Status',['new','contacted','interested','admitted','not_interested','lost'],String(v('status')||'new'))}${field('enqNotes','Notes','Optional',undefined,String(v('notes')))}</div><div class="form-actions"><button class="outline-btn" data-page="enquiries">Cancel</button><button class="primary-btn" id="saveEnquiry">${existing?'Update':'Save'} Enquiry</button></div></div></main>`;bind();document.getElementById('saveEnquiry')!.onclick=async()=>{const name=(document.getElementById('enqName') as HTMLInputElement).value.trim();if(!name)return alert('Name is required.');const payload={institute_id:c.instituteId,name,phone:(document.getElementById('enqPhone') as HTMLInputElement).value.trim()||null,course_id:(document.getElementById('enqCourse') as HTMLSelectElement).value||null,batch_id:(document.getElementById('enqBatch') as HTMLSelectElement).value||null,source:(document.getElementById('enqSource') as HTMLInputElement).value.trim()||null,follow_up_date:(document.getElementById('enqFollow') as HTMLInputElement).value||null,status:(document.getElementById('enqStatus') as HTMLSelectElement).value,notes:(document.getElementById('enqNotes') as HTMLInputElement).value.trim()||null};const r=existing?await supabase.from('enquiries').update(payload).eq('id',existing.id):await supabase.from('enquiries').insert(payload);if(r.error)return alert(`Enquiry save failed: ${r.error.message}`);await enquiriesPage()}}


async function reportsPage(){
 const c=await context();if(!c)return;
 const month=new Date().toISOString().slice(0,7);app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>Reports</h1><p>Monthly management summary from live Supabase data.</p></div><input id="reportMonth" type="month" value="${month}" class="month-input"/></div><div id="reportBody" class="content-card"><div class="empty-state"><h3>Loading report...</h3></div></div></main>`;bind();
 const render=async()=>{const m=(document.getElementById('reportMonth') as HTMLInputElement).value||month,from=`${m}-01`,d=new Date(`${from}T00:00:00`),to=new Date(d.getFullYear(),d.getMonth()+1,1).toISOString().slice(0,10);
 const [st,fees,pay,exp,sal,att]=await Promise.all([
  supabase.from('students').select('id,status').eq('institute_id',c.instituteId),
  supabase.from('fees').select('amount,discount,due_amount,status,created_at').eq('institute_id',c.instituteId).gte('created_at',from).lt('created_at',to),
  supabase.from('fee_payments').select('amount,payment_date,payment_method').eq('institute_id',c.instituteId).gte('payment_date',from).lt('payment_date',to),
  supabase.from('expenses').select('amount,expense_date').eq('institute_id',c.instituteId).gte('expense_date',from).lt('expense_date',to),
  supabase.from('salaries').select('salary_amount,paid_amount,month,year').eq('institute_id',c.instituteId).eq('month',Number(from.slice(5,7))).eq('year',Number(from.slice(0,4))),
  supabase.from('attendance').select('status,attendance_date').eq('institute_id',c.instituteId).gte('attendance_date',from).lt('attendance_date',to)
 ]);
 const err=[st,fees,pay,exp,sal,att].find(x=>x.error);if(err){document.getElementById('reportBody')!.innerHTML=`<div class="empty-state"><h3>Report could not load</h3><p>${esc(err.error!.message)}</p></div>`;return}
 const students=(st.data||[]),collection=(pay.data||[]).reduce((a:any,x:any)=>a+Number(x.amount||0),0),general=(exp.data||[]).reduce((a:any,x:any)=>a+Number(x.amount||0),0),salary=(sal.data||[]).reduce((a:any,x:any)=>a+Number(x.paid_amount||0),0),feeDue=(fees.data||[]).reduce((a:any,x:any)=>a+Math.max(0,Number(x.due_amount||0)),0),attn=(att.data||[]),present=attn.filter((x:any)=>x.status==='present').length,attendanceRate=attn.length?Math.round(present/attn.length*100):0,net=collection-general-salary;
 document.getElementById('reportBody')!.innerHTML=`<div class="stats-grid"><div class="stat-card"><i>💰</i><span>Collection<strong>৳${collection.toFixed(2)}</strong></span></div><div class="stat-card"><i>📌</i><span>Fee Due<strong>৳${feeDue.toFixed(2)}</strong></span></div><div class="stat-card"><i>🧾</i><span>Expenses<strong>৳${general.toFixed(2)}</strong></span></div><div class="stat-card"><i>📈</i><span>Net Cash<strong>৳${net.toFixed(2)}</strong></span></div></div><div class="report-grid"><div><h3>Students</h3><p>Total: <b>${students.length}</b> · Active: <b>${students.filter((x:any)=>x.status==='active').length}</b></p></div><div><h3>Attendance</h3><p>${attendanceRate}% present rate · ${attn.length} records</p></div><div><h3>Salary Paid</h3><p>৳${salary.toFixed(2)}</p></div><div><h3>Fees Created</h3><p>${(fees.data||[]).length} fee entries</p></div></div>`};await render();document.getElementById('reportMonth')!.addEventListener('change',render)
}

