  const studentOpts=st.map((x:any)=>`<option value="${esc(x.id)}">${esc(x.full_name||x.student_id||x.id)}</option>`).join('');
  const teacherOpts=ts.map((x:any)=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.designation||'Teacher')}</option>`).join('');
