function placeholder(title:string){app.innerHTML=`${header()}<main class="dashboard"><div class="page-header"><div><h1>${title}</h1><p>Module development is next in the build sequence.</p></div></div><div class="content-card empty-state"><div class="big-icon">🚧</div><h2>${title}</h2><p>This module is not being faked with demo data. It will be connected to Supabase during its implementation.</p></div></main>`;bind()}
async function go(p:string){
  setGlobalLoading(true,'Opening module...');
  try{
  if(p==='platform-admin'){await platformAdminPage();return}
  const c=await context(); if(!c)return;
  const adminOnly=['roles'];
  const managerOnly=['subscription','students','courses','batches','fees','staff','expenses','profit-loss','reports','enquiries','settings'];
  const allStaff=['attendance','attendance-history','routine','homework','assignments','exams','results-center','enquiries','notifications'];
  if(c.role==='student')return ['dashboard','results-center'].includes(p)?(p==='dashboard'?dashboard():resultsCenterPage()):accessDenied();
  if(c.role==='teacher' && !['dashboard','attendance','attendance-history','routine','homework','assignments','recorded-classes','exams','results-center','notifications'].includes(p))return accessDenied();
  if(c.role==='staff' && !['dashboard','attendance','attendance-history','routine','homework','assignments','exams','results-center','notifications'].includes(p))return accessDenied();
  if(managerOnly.includes(p)&&!(c.role==='admin'||c.role==='manager'))return accessDenied();
  if(adminOnly.includes(p)&&c.role!=='admin')return accessDenied();
  if(p==='dashboard')dashboard();else if(p==='students')studentsPage();else if(p==='courses')coursesPage();else if(p==='batches')batchesPage();else if(p==='subscription')subscriptionPage();else if(p==='fees')feesPage();else if(p==='monthly-fees')monthlyFeeForm();else if(p==='attendance')attendancePage();else if(p==='attendance-history')attendanceHistoryPage();else if(p==='attendance-monthly-report')attendanceMonthlyReportPage();else if(p==='routine')routinePage();else if(p==='staff')staffPage();else if(p==='expenses')expensesPage();else if(p==='profit-loss')profitLossPage();else if(p==='reports')reportsPage();else if(p==='notifications')notificationsPage();else if(p==='settings')settingsPage();else if(p==='roles')rolePage();else if(p==='homework')academicPage('homework');else if(p==='assignments')academicPage('assignments');else if(p==='recorded-classes')recordedClassesPage();else if(p==='exams')examsPage();else if(p==='results-center')resultsCenterPage();else if(p==='enquiries')enquiriesPage();else if(p==='add')studentForm();else placeholder(p.charAt(0).toUpperCase()+p.slice(1))
  }catch(e){showRuntimeError((e as any)?.message||String(e))}finally{setGlobalLoading(false)}
}

supabase.auth.onAuthStateChange((_e,s)=>{if(!s){studentsCache=[];instituteId=null}})
;(async()=>{if(!authGuard())return;const {data}=await supabase.auth.getSession();if(data.session){const pa=await supabase.rpc('is_platform_admin');isPlatformAdmin=!pa.error&&pa.data===true;const hash=location.hash.toLowerCase();if(hash.includes('type=recovery')||hash.includes('access_token')){updatePasswordPage()}else if(isPlatformAdmin && !(await supabase.rpc('get_my_institute_id')).data){await platformAdminPage()}else await dashboard()}else login()})()
